insert into mdl.questions (ext_key, bank, selection, kind, text, options, correct_index, explanation, category,
  difficulty, time_limit_sec, sort_order, guide_short, guide_long, guide_location, guide_practical, guide_sources,
  guide_fact, guide_visibility, i18n, guide_i18n, route_meta)
values
($v3$v3:ROAD67-11$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$המושבה זכרון יעקב נקראה על שם —$v3$, $v3$["אביו של הברון רוטשילד, ג'יימס (יעקב)","יעקב אבינו","המייסד הראשון של המושבה","הנהג הראשון שהגיע אליה"]$v3$::jsonb, 0, $v3$זכרון יעקב נוסדה ב-1882 ונקראה על שם ג'יימס (יעקב) רוטשילד, אביו של הברון אדמונד דה רוטשילד, שתמך במושבה.$v3$, $v3$היסטוריה$v3$, 2, 45, 1, $v3$נקראה על שם ג׳יימס-יעקב, אביו של הברון רוטשילד. בזכותו — כרמים ויקב.$v3$, $v3$אנחנו יוצאים מזכרון יעקב, אחת המושבות הראשונות של העלייה הראשונה. היא נוסדה ב-1882 בידי עולים מרומניה, והחיים היו קשים מאוד: מחלות, יובש וחובות. הברון אדמונד דה רוטשילד לקח אותה תחת חסותו, והמושבה נקראה על שם אביו — ג'יימס, יעקב בעברית. בזכותו נבנו כאן כרמים ויקב גדול, ועד היום זכרון יעקב מזוהה עם יין ועם המשפחה הזאת.$v3$, $v3$בתחילת הנסיעה, ביציאה מזכרון יעקב (מחלף זכרון יעקב / צומת פוריידיס).$v3$, $v3$יוסי: זכרון יעקב — על שם אביו של הנדיב הידוע (ג'יימס = יעקב), היישוב השני של העלייה הראשונה (טענה זו לא נכללה). אומת: נוסדה ב-1882, נקראה ב-1883 על שם ג'יימס (יעקב) רוטשילד, אביו של הברון אדמונד.$v3$, $v3$[{"title":"Zikhron Ya'akov — Wikipedia","url":"https://en.wikipedia.org/wiki/Zikhron_Ya%27akov"}]$v3$::jsonb, $v3$בהמשך הדרך נפגוש עוד שני דורות של רוטשילדים: מאיר שפיה על שם הסבא, ובת שלמה על שם האמא.$v3$, $v3$check$v3$, $v3${"fr":{"text":"La colonie de Zikhron Yaakov porte le nom…","options":["du père du baron de Rothschild, James (Yaakov)","du patriarche Jacob","du premier fondateur de la colonie","du premier chauffeur arrivé ici"],"explanation":"Zikhron Yaakov, fondée en 1882, porte le nom de James (Yaakov) de Rothschild, père du baron Edmond de Rothschild qui soutenait la colonie.","category":"Histoire"},"en":{"text":"The colony of Zikhron Ya'akov is named after —","options":["Baron Rothschild's father, James (Ya'akov)","the patriarch Jacob","the colony's first founder","the first driver who arrived there"],"explanation":"Zikhron Ya'akov was founded in 1882 and named after James (Ya'akov) de Rothschild, father of Baron Edmond de Rothschild, who supported the colony.","category":"History"},"ru":{"text":"Колония Зихрон-Яаков названа в честь…","options":["отца барона Ротшильда — Джеймса (Яакова)","праотца Иакова","первого основателя колонии","первого водителя, приехавшего сюда"],"explanation":"Зихрон-Яаков основан в 1882 году и назван в честь Джеймса (Яакова) Ротшильда — отца барона Эдмона де Ротшильда, поддерживавшего колонию.","category":"История"}}$v3$::jsonb, $v3${"he":{"script":"נקראה על שם ג׳יימס-יעקב, אביו של הברון רוטשילד. בזכותו — כרמים ויקב.","long":"אנחנו יוצאים מזכרון יעקב, אחת המושבות הראשונות של העלייה הראשונה. היא נוסדה ב-1882 בידי עולים מרומניה, והחיים היו קשים מאוד: מחלות, יובש וחובות. הברון אדמונד דה רוטשילד לקח אותה תחת חסותו, והמושבה נקראה על שם אביו — ג'יימס, יעקב בעברית. בזכותו נבנו כאן כרמים ויקב גדול, ועד היום זכרון יעקב מזוהה עם יין ועם המשפחה הזאת.","fact":"בהמשך הדרך נפגוש עוד שני דורות של רוטשילדים: מאיר שפיה על שם הסבא, ובת שלמה על שם האמא.","cue":"בתחילת הנסיעה, ביציאה מזכרון יעקב (מחלף זכרון יעקב / צומת פוריידיס).","caution":"הצד לא אומת: לפי מסמך יוסי זכרון יעקב מימין. לא להצביע על בניין מסוים."},"fr":{"script":"Elle porte le nom de James-Yaakov, le père du baron de Rothschild. Grâce à lui : des vignes et une cave.","long":"Nous partons de Zikhron Yaakov, l'une des premières colonies de la première alya. Elle est fondée en 1882 par des immigrants de Roumanie, et la vie y est très dure : maladies, sécheresse et dettes. Le baron Edmond de Rothschild la prend sous sa protection, et la colonie reçoit le nom de son père, James, Yaakov en hébreu. Grâce à lui, on plante des vignes et on construit une grande cave : aujourd'hui encore, Zikhron rime avec vin et avec cette famille.","fact":"Plus loin, nous croiserons deux autres générations de Rothschild : Meir Shfeya pour le grand-père, et Bat Shlomo pour la mère.","cue":"Au début du trajet, en quittant Zikhron Yaakov (échangeur de Zikhron / carrefour de Fureidis).","caution":"Côté non vérifié : selon le document de Yossi, Zikhron est à droite. Ne pas désigner un bâtiment précis."},"en":{"script":"Named after James-Ya'akov, Baron Rothschild's father. Thanks to him: vineyards and a winery.","long":"We're leaving Zikhron Ya'akov, one of the first colonies of the First Aliyah. It was founded in 1882 by immigrants from Romania, and life was very hard: disease, drought and debt. Baron Edmond de Rothschild took it under his wing, and the colony was named after his father — James, Ya'akov in Hebrew. Thanks to him, vineyards and a big winery were built here, and to this day Zikhron is linked with wine and with that family.","fact":"Further along we'll meet two more generations of Rothschilds: Meir Shfeya for the grandfather and Bat Shlomo for the mother.","cue":"At the start of the drive, leaving Zikhron Ya'akov (Zikhron interchange / Fureidis junction).","caution":"Side not verified: according to Yossi's notes Zikhron is on the right. Don't point at a specific building."},"ru":{"script":"Названа в честь Джеймса-Яакова, отца барона Ротшильда. Благодаря ему — виноградники и винодельня.","long":"Мы выезжаем из Зихрон-Яакова — одной из первых колоний Первой алии. Её основали в 1882 году выходцы из Румынии, и жизнь здесь была очень тяжёлой: болезни, засуха и долги. Барон Эдмон де Ротшильд взял колонию под опеку, и её назвали в честь его отца — Джеймса, по-еврейски Яакова. Благодаря ему здесь посадили виноградники и построили большую винодельню, и до сих пор Зихрон связан с вином и с этой семьёй.","fact":"Дальше по дороге нас ждут ещё два поколения Ротшильдов: Меир-Шфея — в честь деда, Бат-Шломо — в честь матери.","cue":"В начале поездки, при выезде из Зихрон-Яакова (развязка Зихрон / перекрёсток Фурейдис).","caution":"Сторона не проверена: по записям Йоси Зихрон справа. Не показывать на конкретное здание."}}$v3$::jsonb, $v3${"stop":"S11","final":false,"topic":"Zikhron Yaakov name","docs":"יוסי: זכרון יעקב — על שם אביו של הנדיב הידוע (ג'יימס = יעקב), היישוב השני של העלייה הראשונה (טענה זו לא נכללה). אומת: נוסדה ב-1882, נקראה ב-1883 על שם ג'יימס (יעקב) רוטשילד, אביו של הברון אדמונד."}$v3$::jsonb),
($v3$v3:ROAD67-12$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$מה פירוש השם פוריידיס בערבית?$v3$, $v3$["גן עדן קטן","מעיין מלוח","גבעה לבנה","כפר הדייגים"]$v3$::jsonb, 0, $v3$פוריידיס פירושו 'גן עדן קטן' — מאותו שורש של המילים 'פרדס' בעברית ו-paradise באנגלית.$v3$, $v3$שפה ושמות$v3$, 2, 45, 2, $v3$בערבית ״גן עדן קטן״. מאותה מילה: פרדס, paradise.$v3$, $v3$משמאלנו, לפי שני המסמכים, הכפר פוריידיס, למרגלות הכרמל. לשם יש סיפור יפה: פוריידיס בערבית זה 'גן עדן קטן'. המילה הגיעה מפרסית עתיקה, שם 'פרדס' היה גן מוקף חומה. מאותה מילה נולדו גם 'פרדס' בעברית וגם paradise באנגלית ו-paradis בצרפתית. כלומר — שלוש שפות, מילה אחת, וכולן מתחילות בגן.$v3$, $v3$ליד צומת פוריידיס (כביש 4), בתחילת כביש 67.$v3$, $v3$יאיר: פוריידיס משמאלנו; השם מהמילה הפרסית 'פרדס' — 'גן עדן' (paradise); מרכז מסחרי חדש בכניסה (לא נכלל). יוסי: משמאל; השם = פרדס / גן עדן / הורדוס (הורדוס לא נכלל). אומת: 'פֻרַידִיס' בערבית — 'גן עדן קטן'.$v3$, $v3$[{"title":"Fureidis — Wikipedia","url":"https://en.wikipedia.org/wiki/Fureidis"}]$v3$::jsonb, $v3$'פרדס' מופיע כבר בתנ״ך, בשיר השירים: 'פרדס רימונים עם פרי מגדים'.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Que signifie le nom arabe Fureidis ?","options":["Petit paradis","Source salée","Colline blanche","Village de pêcheurs"],"explanation":"Fureidis signifie « petit paradis » : la même racine que « pardès » en hébreu, « paradis » en français et « paradise » en anglais.","category":"Langue et noms"},"en":{"text":"What does the Arabic name Fureidis mean?","options":["Little paradise","Salty spring","White hill","Fishermen's village"],"explanation":"Fureidis means 'little paradise' — the same root as 'pardes' in Hebrew and 'paradise' in English.","category":"Names and language"},"ru":{"text":"Что означает арабское название Фурейдис?","options":["Маленький рай","Солёный источник","Белый холм","Рыбацкая деревня"],"explanation":"Фурейдис означает «маленький рай» — тот же корень, что у ивритского «пардес» и английского «paradise».","category":"Названия"}}$v3$::jsonb, $v3${"he":{"script":"בערבית ״גן עדן קטן״. מאותה מילה: פרדס, paradise.","long":"משמאלנו, לפי שני המסמכים, הכפר פוריידיס, למרגלות הכרמל. לשם יש סיפור יפה: פוריידיס בערבית זה 'גן עדן קטן'. המילה הגיעה מפרסית עתיקה, שם 'פרדס' היה גן מוקף חומה. מאותה מילה נולדו גם 'פרדס' בעברית וגם paradise באנגלית ו-paradis בצרפתית. כלומר — שלוש שפות, מילה אחת, וכולן מתחילות בגן.","fact":"'פרדס' מופיע כבר בתנ״ך, בשיר השירים: 'פרדס רימונים עם פרי מגדים'.","cue":"ליד צומת פוריידיס (כביש 4), בתחילת כביש 67.","caution":"הצד לא אומת: שני המסמכים — משמאל. לא להצביע עד אימות."},"fr":{"script":"En arabe, « petit paradis ». Le même mot a donné « pardès », « paradise » et « paradis ».","long":"Sur notre gauche, d'après les deux documents, le village de Fureidis, au pied du Carmel. Son nom a une belle histoire : Fureidis, en arabe, veut dire « petit paradis ». Le mot vient du vieux perse, où le « pardès » était un jardin entouré d'un mur. De ce même mot sont nés « pardès » en hébreu, « paradise » en anglais et « paradis » en français. Trois langues, un seul mot, et tout commence par un jardin.","fact":"Le mot « pardès » figure déjà dans la Bible, dans le Cantique des cantiques : « un jardin de grenadiers aux fruits exquis ».","cue":"Près du carrefour de Fureidis (route 4), au début de la route 67.","caution":"Côté non vérifié : les deux documents disent à gauche. Ne pas montrer avant vérification."},"en":{"script":"In Arabic, 'little paradise'. The same word gave us 'pardes' and 'paradise'.","long":"On our left, according to both guide documents, is the village of Fureidis at the foot of the Carmel. Its name has a lovely story: Fureidis in Arabic means 'little paradise'. The word comes from Old Persian, where a 'pardes' was a walled garden. From that same word came 'pardes' in Hebrew, 'paradise' in English and 'paradis' in French. Three languages, one word — and it all starts with a garden.","fact":"'Pardes' already appears in the Bible, in the Song of Songs: 'an orchard of pomegranates, with pleasant fruits'.","cue":"Near Fureidis junction (Road 4), at the start of Road 67.","caution":"Side not verified: both documents say left. Don't point until checked."},"ru":{"script":"По-арабски «маленький рай». От того же слова — «пардес» и «paradise».","long":"Слева от нас, по обоим документам, деревня Фурейдис у подножия Кармеля. У названия красивая история: по-арабски Фурейдис значит «маленький рай». Слово пришло из древнеперсидского, где «пардес» — это сад, обнесённый стеной. От этого же слова произошли ивритское «пардес», английское «paradise» и французское «paradis». Три языка, одно слово — и всё начинается с сада.","fact":"Слово «пардес» встречается уже в Библии, в Песни песней: «сад с гранатовыми яблоками, с превосходными плодами».","cue":"У перекрёстка Фурейдис (дорога 4), в начале шоссе 67.","caution":"Сторона не проверена: в обоих документах — слева. Не показывать до проверки."}}$v3$::jsonb, $v3${"stop":"S12","final":false,"topic":"Fureidis name","docs":"יאיר: פוריידיס משמאלנו; השם מהמילה הפרסית 'פרדס' — 'גן עדן' (paradise); מרכז מסחרי חדש בכניסה (לא נכלל). יוסי: משמאל; השם = פרדס / גן עדן / הורדוס (הורדוס לא נכלל). אומת: 'פֻרַידִיס' בערבית — 'גן עדן קטן'."}$v3$::jsonb),
($v3$v3:ROAD67-01$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$כביש 67 עובר בוואדי מילק (ואדי אל-מילח). מה חשיבותו של המעבר הזה?$v3$, $v3$["מעבר טבעי נוח בין מישור החוף לעמק יזרעאל","הדרך הקצרה מחיפה לים המלח","תעלת מים שחפרו הרומאים","הגבול בין ישראל ללבנון"]$v3$::jsonb, 0, $v3$ואדי מילח עובר בין הכרמל לרמות מנשה ומחבר את מישור החוף לעמק יזרעאל — אחד המעברים הנוחים בצפון הארץ.$v3$, $v3$גאוגרפיה$v3$, 2, 45, 3, $v3$מעבר טבעי בין הים לעמק יזרעאל — הכרמל מצפון, רמות מנשה מדרום.$v3$, $v3$אנחנו נכנסים עכשיו לוואדי מילק — שיבוש של השם הערבי ואדי אל-מילח, 'ואדי המלח'. מצפון לנו רכס הכרמל, מדרום רמות מנשה, ובאמצע מסדרון טבעי שמוביל מהים אל עמק יזרעאל. הכביש עולה במעלה נחל דליה ונחל תות, ובסוף, ליד יקנעם, נפתח אל העמק. לכן עברו כאן לאורך הדורות שיירות וצבאות — והיום גם אנחנו.$v3$, $v3$בתחילת הנסיעה, אחרי צומת פוריידיס, כשהכביש נכנס בין הכרמל (צפון) לרמות מנשה (דרום). שאלה כללית — אין אתר להצביע עליו.$v3$, $v3$יאיר: ואדי מילק = ואדי אל-מילח, מעבר בין מישור החוף לעמק יזרעאל, 'חלק מדרך הים'. יוסי: עולים בנחל דליה; השם שובש בפי האנגלים; 'הובילו מלח'. תיקון: המעבר הראשי של דרך הים היה בוואדי ערה (נחל עירון); ואדי מילח הוא מעבר משני. הסברי 'האנגלים' ו'שיירות המלח' הם מסורות לא מתועדות.$v3$, $v3$[{"title":"Highway 67 (Israel) — Wikipedia","url":"https://en.wikipedia.org/wiki/Highway_67_(Israel)"},{"title":"נחל תות — המכלול","url":"https://www.hamichlol.org.il/נחל_תות"}]$v3$::jsonb, $v3$המעבר הראשי של 'דרך הים' העתיקה עבר דווקא בוואדי ערה, בנחל עירון. ואדי מילח היה מעבר משני — אבל הוא אחד משני הצירים המרכזיים שחוצים היום את הכרמל (השני: כביש 65 בוואדי ערה).$v3$, $v3$topic$v3$, $v3${"fr":{"text":"La route 67 emprunte le Wadi Milk (Wadi al-Milh). Quel est l'intérêt de ce passage ?","options":["Un passage naturel commode entre la plaine côtière et la vallée de Jezréel","Le plus court chemin de Haïfa à la mer Morte","Un canal creusé par les Romains","La frontière entre Israël et le Liban"],"explanation":"Le Wadi Milh passe entre le Carmel et les collines de Menashe et relie la plaine côtière à la vallée de Jezréel : l'un des passages les plus faciles du nord du pays.","category":"Géographie"},"en":{"text":"Road 67 runs through Wadi Milk (Wadi al-Milh). Why is this pass important?","options":["An easy natural pass between the coastal plain and the Jezreel Valley","The shortest road from Haifa to the Dead Sea","A water channel dug by the Romans","The border between Israel and Lebanon"],"explanation":"Wadi Milh runs between Mount Carmel and the Menashe Heights, linking the coastal plain with the Jezreel Valley — one of the easiest passes in northern Israel.","category":"Geography"},"ru":{"text":"Шоссе 67 проходит по Вади-Милк (Вади-эль-Мильх). Чем важен этот проход?","options":["Удобный естественный проход между прибрежной равниной и Изреельской долиной","Самая короткая дорога из Хайфы к Мёртвому морю","Канал, вырытый римлянами","Граница между Израилем и Ливаном"],"explanation":"Вади-Мильх проходит между Кармелем и возвышенностью Менаше и соединяет прибрежную равнину с Изреельской долиной — один из самых удобных проходов на севере страны.","category":"География"}}$v3$::jsonb, $v3${"he":{"script":"מעבר טבעי בין הים לעמק יזרעאל — הכרמל מצפון, רמות מנשה מדרום.","long":"אנחנו נכנסים עכשיו לוואדי מילק — שיבוש של השם הערבי ואדי אל-מילח, 'ואדי המלח'. מצפון לנו רכס הכרמל, מדרום רמות מנשה, ובאמצע מסדרון טבעי שמוביל מהים אל עמק יזרעאל. הכביש עולה במעלה נחל דליה ונחל תות, ובסוף, ליד יקנעם, נפתח אל העמק. לכן עברו כאן לאורך הדורות שיירות וצבאות — והיום גם אנחנו.","fact":"המעבר הראשי של 'דרך הים' העתיקה עבר דווקא בוואדי ערה, בנחל עירון. ואדי מילח היה מעבר משני — אבל הוא אחד משני הצירים המרכזיים שחוצים היום את הכרמל (השני: כביש 65 בוואדי ערה).","cue":"בתחילת הנסיעה, אחרי צומת פוריידיס, כשהכביש נכנס בין הכרמל (צפון) לרמות מנשה (דרום). שאלה כללית — אין אתר להצביע עליו.","caution":"מסמך יאיר כותב שהמעבר היה 'חלק מדרך הים' — מדויק יותר: אחד ממעברי הכרמל. ההסבר שהאנגלים שיבשו את השם — מסורת, לא עובדה מתועדת."},"fr":{"script":"Un passage naturel entre la mer et la vallée de Jezréel : le Carmel au nord, Menashe au sud.","long":"Nous entrons dans le Wadi Milk, déformation de l'arabe Wadi al-Milh, « la vallée du sel ». Au nord, la chaîne du Carmel ; au sud, les collines de Menashe ; entre les deux, un couloir naturel qui mène de la mer à la vallée de Jezréel. La route remonte le Nahal Dalia puis le Nahal Tut et débouche sur la vallée près de Yokneam. Caravanes et armées l'ont emprunté pendant des siècles — et nous aujourd'hui.","fact":"Le grand passage de l'antique « Via Maris » se trouvait en fait au Wadi Ara (Nahal Iron). Le Wadi Milh était un passage secondaire — mais c'est aujourd'hui l'un des deux grands axes qui traversent le Carmel, avec la route 65 du Wadi Ara.","cue":"Au début du trajet, après le carrefour de Fureidis, quand la route s'engage entre le Carmel (nord) et Menashe (sud). Question générale : rien à montrer du doigt.","caution":"Le document de Yaïr parle de la « Via Maris » : plus exact de dire « l'un des passages du Carmel ». L'explication « ce sont les Britanniques qui ont déformé le nom » est une tradition non documentée."},"en":{"script":"A natural pass from the sea to the Jezreel Valley: the Carmel to the north, Menashe to the south.","long":"We're now entering Wadi Milk — a garbled form of the Arabic Wadi al-Milh, 'the valley of salt'. To the north is the Carmel ridge, to the south the Menashe Heights, and in between a natural corridor from the sea to the Jezreel Valley. The road climbs along Nahal Dalia and Nahal Tut and opens onto the valley near Yokneam. Caravans and armies used it for centuries — and today, so do we.","fact":"The main pass of the ancient 'Way of the Sea' was actually in Wadi Ara, along Nahal Iron. Wadi Milh was a secondary pass — but today it's one of the two main roads across the Carmel, together with Road 65 in Wadi Ara.","cue":"Early in the drive, after Fureidis junction, as the road enters between the Carmel (north) and the Menashe Heights (south). A general question — nothing to point at.","caution":"Yair's notes call it 'part of the Via Maris' — more accurate: one of the Carmel passes. 'The British garbled the name' is a tradition, not a documented fact."},"ru":{"script":"Естественный проход от моря к Изреельской долине: Кармель на севере, Менаше на юге.","long":"Мы въезжаем в Вади-Милк — искажённое арабское Вади-эль-Мильх, «долина соли». На севере — хребет Кармель, на юге — возвышенность Менаше, а между ними естественный коридор от моря к Изреельской долине. Дорога поднимается вдоль ручьёв Далия и Тут и у Йокнеама выходит в долину. Здесь веками шли караваны и армии — а сегодня едем мы.","fact":"Главный проход древней «Приморской дороги» на самом деле шёл через Вади-Ара, по ручью Ирон. Вади-Мильх был второстепенным проходом, но сегодня это одна из двух главных дорог через Кармель — вместе с шоссе 65 в Вади-Ара.","cue":"В начале поездки, после перекрёстка Фурейдис, когда дорога входит между Кармелем (север) и Менаше (юг). Общий вопрос — показывать ничего не нужно.","caution":"В записях Яира сказано «часть Приморской дороги» — точнее: «один из проходов через Кармель». Версия «название исказили британцы» — предание, а не документированный факт."}}$v3$::jsonb, $v3${"stop":"S1","final":false,"topic":"Wadi Milh pass","docs":"יאיר: ואדי מילק = ואדי אל-מילח, מעבר בין מישור החוף לעמק יזרעאל, 'חלק מדרך הים'. יוסי: עולים בנחל דליה; השם שובש בפי האנגלים; 'הובילו מלח'. תיקון: המעבר הראשי של דרך הים היה בוואדי ערה (נחל עירון); ואדי מילח הוא מעבר משני. הסברי 'האנגלים' ו'שיירות המלח' הם מסורות לא מתועדות."}$v3$::jsonb),
($v3$v3:ROAD67-02$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$מי הקים בשנת 1904 בשפיה מוסד לילדים יתומים שניצלו מפרעות קישינב?$v3$, $v3$["דוד בן-גוריון","ישראל בלקינד","בנימין זאב הרצל","מאיר דיזנגוף"]$v3$::jsonb, 1, $v3$ישראל בלקינד, ממייסדי ביל״ו, הקים כאן ב-1904 מוסד ליתומי פרעות קישינב — ראשיתו של כפר הנוער מאיר שפיה.$v3$, $v3$היסטוריה$v3$, 2, 45, 4, $v3$ב-1904 ישראל בלקינד הביא לכאן יתומי פרעות קישינב — כנראה כפר הנוער הראשון בארץ.$v3$, $v3$השם מאיר שפיה מחבר שני עולמות: 'מאיר' — על שם מאיר אמשל רוטשילד, סבו של הברון, ו'שפיה' — שם הכפר הערבי שהיה כאן. ב-1904 הביא לכאן ישראל בלקינד, ממייסדי ביל״ו, ילדים יתומים שניצלו מפרעות קישינב. הם למדו, עבדו בחקלאות וחיו יחד — כנראה כפר הנוער הראשון בארץ. גם היום זה כפר נוער עם פנימייה, חקלאות וכרם.$v3$, $v3$כ-4 ק״מ מתחילת כביש 67, באזור צומת שפיה (כביש 652). לספר בלי להצביע.$v3$, $v3$יאיר: 'הסתכלו שמאלה'; על שם מאיר רוטשילד, סבו של הברון; בלקינד 1904, יתומי קישינב, כפר הנוער הראשון. יוסי: 'מצד שמאל'; שיר של ביאליק על בנות שפיה (לא אומת — לא נכלל). אזהרה: לפי קואורדינטות ויקיפדיה (32.590, 34.971) הכפר קרוב מאוד לציר — הצד לא אומת.$v3$, $v3$[{"title":"Meir Shfeya — Wikipedia","url":"https://en.wikipedia.org/wiki/Meir_Shfeya"},{"title":"ישראל בלקינד — ויקיפדיה","url":"https://he.wikipedia.org/wiki/ישראל_בלקינד"}]$v3$::jsonb, $v3$בלקינד היה מורה — והרעיון שלו, 'בית ספר שהוא גם משק', הפך לדגם של כפרי הנוער בישראל: לומדים בבוקר, עובדים בשדה אחר הצהריים.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Qui a fondé à Shfeya, en 1904, une institution pour des orphelins rescapés du pogrom de Kichinev ?","options":["David Ben Gourion","Israel Belkind","Theodor Herzl","Meir Dizengoff"],"explanation":"Israel Belkind, l'un des fondateurs du mouvement Bilou, y a créé en 1904 un foyer pour les orphelins du pogrom de Kichinev : le début du village de jeunes Meir Shfeya.","category":"Histoire"},"en":{"text":"Who founded an institution at Shfeya in 1904 for orphans who survived the Kishinev pogrom?","options":["David Ben-Gurion","Israel Belkind","Theodor Herzl","Meir Dizengoff"],"explanation":"Israel Belkind, one of the founders of the Bilu movement, set up a home here in 1904 for orphans of the Kishinev pogrom — the beginning of the Meir Shfeya youth village.","category":"History"},"ru":{"text":"Кто основал в Шфее в 1904 году приют для сирот, переживших Кишинёвский погром?","options":["Давид Бен-Гурион","Исраэль Белкинд","Теодор Герцль","Меир Дизенгоф"],"explanation":"Исраэль Белкинд, один из основателей движения БИЛУ, открыл здесь в 1904 году приют для сирот Кишинёвского погрома — с него начался молодёжный посёлок Меир-Шфея.","category":"История"}}$v3$::jsonb, $v3${"he":{"script":"ב-1904 ישראל בלקינד הביא לכאן יתומי פרעות קישינב — כנראה כפר הנוער הראשון בארץ.","long":"השם מאיר שפיה מחבר שני עולמות: 'מאיר' — על שם מאיר אמשל רוטשילד, סבו של הברון, ו'שפיה' — שם הכפר הערבי שהיה כאן. ב-1904 הביא לכאן ישראל בלקינד, ממייסדי ביל״ו, ילדים יתומים שניצלו מפרעות קישינב. הם למדו, עבדו בחקלאות וחיו יחד — כנראה כפר הנוער הראשון בארץ. גם היום זה כפר נוער עם פנימייה, חקלאות וכרם.","fact":"בלקינד היה מורה — והרעיון שלו, 'בית ספר שהוא גם משק', הפך לדגם של כפרי הנוער בישראל: לומדים בבוקר, עובדים בשדה אחר הצהריים.","cue":"כ-4 ק״מ מתחילת כביש 67, באזור צומת שפיה (כביש 652). לספר בלי להצביע.","caution":"שני המסמכים כותבים 'משמאל', אבל לפי קואורדינטות ויקיפדיה הכפר קרוב מאוד לציר וייתכן שהוא מימין. לא להצביע עד אימות בנסיעת הכנה."},"fr":{"script":"En 1904, Israel Belkind y accueille des orphelins du pogrom de Kichinev : sans doute le premier village de jeunes du pays.","long":"Le nom Meir Shfeya réunit deux mondes : « Meir », pour Mayer Amschel Rothschild, le grand-père du Baron, et « Shfeya », le nom du village arabe qui se trouvait ici. En 1904, Israel Belkind, l'un des fondateurs du Bilou, y amène des orphelins rescapés du pogrom de Kichinev. Ils étudient, travaillent la terre et vivent ensemble : sans doute le premier village de jeunes du pays. C'est encore aujourd'hui un internat avec ferme et vignoble.","fact":"Belkind était enseignant. Son idée — « une école qui est aussi une ferme » — est devenue le modèle des villages de jeunes israéliens : la classe le matin, les champs l'après-midi.","cue":"Environ 4 km après le début de la route 67, vers le carrefour de Shfeya (route 652). Raconter sans montrer du doigt.","caution":"Les deux documents disent « à gauche », mais d'après les coordonnées de Wikipédia le village est tout près de l'axe et pourrait être à droite. Ne pas montrer avant vérification sur place."},"en":{"script":"In 1904 Israel Belkind brought orphans of the Kishinev pogrom here — probably the country's first youth village.","long":"The name Meir Shfeya joins two worlds: 'Meir' after Mayer Amschel Rothschild, the Baron's grandfather, and 'Shfeya', the name of the Arab village that stood here. In 1904 Israel Belkind, one of the Bilu founders, brought orphans who had survived the Kishinev pogrom. They studied, farmed and lived together — probably the first youth village in the country. Today it is still a boarding school with a farm and a vineyard.","fact":"Belkind was a teacher, and his idea — 'a school that is also a farm' — became the model for Israel's youth villages: classes in the morning, fields in the afternoon.","cue":"About 4 km into Road 67, near Shfeya junction (Road 652). Tell the story without pointing.","caution":"Both guide documents say 'on the left', but by Wikipedia's coordinates the village lies very close to the road and may be on the right. Don't point until checked on a test drive."},"ru":{"script":"В 1904 году Исраэль Белкинд привёз сюда сирот Кишинёвского погрома — вероятно, первый молодёжный посёлок страны.","long":"Название Меир-Шфея соединяет два мира: «Меир» — в честь Майера Амшеля Ротшильда, деда барона, а «Шфея» — название арабской деревни, стоявшей здесь. В 1904 году Исраэль Белкинд, один из основателей БИЛУ, привёз сюда сирот, переживших Кишинёвский погром. Они учились, работали на земле и жили вместе — вероятно, первый молодёжный посёлок в стране. И сегодня здесь интернат с фермой и виноградником.","fact":"Белкинд был учителем, и его идея «школа, которая одновременно ферма» стала образцом для израильских молодёжных посёлков: утром уроки, после обеда — поле.","cue":"Примерно через 4 км после начала шоссе 67, у перекрёстка Шфея (дорога 652). Рассказывать, не показывая рукой.","caution":"В обоих документах написано «слева», но по координатам Википедии посёлок совсем рядом с дорогой и может оказаться справа. Не показывать до проверки на месте."}}$v3$::jsonb, $v3${"stop":"S2","final":false,"topic":"Meir Shfeya youth village","docs":"יאיר: 'הסתכלו שמאלה'; על שם מאיר רוטשילד, סבו של הברון; בלקינד 1904, יתומי קישינב, כפר הנוער הראשון. יוסי: 'מצד שמאל'; שיר של ביאליק על בנות שפיה (לא אומת — לא נכלל). אזהרה: לפי קואורדינטות ויקיפדיה (32.590, 34.971) הכפר קרוב מאוד לציר — הצד לא אומת."}$v3$::jsonb),
($v3$v3:ROAD67-07$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$איזה עץ מאפיין את החורש הטבעי הפתוח של אזור אלונה ורמות מנשה?$v3$, $v3$["דקל התמר","אלון התבור","דקל הקוקוס","ארז הלבנון"]$v3$::jsonb, 1, $v3$אלון התבור — עץ נשיר-למחצה עם עלים רחבים — יוצר כאן 'יער פארק' פתוח וטבעי.$v3$, $v3$בוטניקה$v3$, 2, 45, 5, $v3$חורש טבעי של אלוני תבור — עצים רחבים ומרווחים, לא יער נטוע.$v3$, $v3$הגבעות האלה הן ממלכת אלון התבור. בניגוד ליערות האורנים שנטעה קק״ל, זה חורש טבעי: עצים רחבים ומרווחים, 'יער פארק', על קרקע רנדזינה בהירה שנוצרה מסלע הקירטון. אלון התבור משיר חלק מעליו בחורף — ולכן בסתיו הגבעות מקבלות גוון צהבהב-חום. לא כל עץ שרואים מהחלון הוא אלון תבור, אבל רוב העצים הגדולים והבודדים כאן — כן.$v3$, $v3$בין צומת שפיה לבת שלמה, כשנראה חורש פתוח על הגבעות.$v3$, $v3$יאיר: 'מצד ימין — יערות אלונה, יער אלונים טבעי עד הר חורשן'; מפנה צפוני: אלון מצוי ואלה; מפנה דרומי: אלון התבור ולבנה. יוסי: 'מצד ימין', חורש אלון התבור, קרטון ורנדזינה. אחרי אליקים: יערות אורן נטועים של קק״ל (לא טבעיים).$v3$, $v3$[{"title":"אלון התבור — ויקיפדיה","url":"https://he.wikipedia.org/wiki/אלון_התבור"}]$v3$::jsonb, $v3$אלוני התבור העתיקים בארץ יכולים להגיע לגיל של מאות שנים. בגללם נקראה המועצה האזורית הסמוכה 'אלונה'.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Quel arbre caractérise les bois naturels clairsemés d'Alona et des collines de Menashe ?","options":["Le palmier-dattier","Le chêne du Tabor","Le cocotier","Le cèdre du Liban"],"explanation":"Le chêne du Tabor, à feuilles larges et semi-caduques, forme ici une « forêt-parc » naturelle et ouverte.","category":"Botanique"},"en":{"text":"Which tree characterizes the open natural woodland of Alona and the Menashe Heights?","options":["Date palm","Tabor oak","Coconut palm","Cedar of Lebanon"],"explanation":"The Tabor oak, broad-leaved and semi-deciduous, forms an open natural 'park forest' here.","category":"Botany"},"ru":{"text":"Какое дерево характерно для естественного редколесья района Алона и возвышенности Менаше?","options":["Финиковая пальма","Таворский дуб","Кокосовая пальма","Ливанский кедр"],"explanation":"Таворский дуб — широколиственный, полулистопадный — образует здесь естественный светлый «парковый лес».","category":"Ботаника"}}$v3$::jsonb, $v3${"he":{"script":"חורש טבעי של אלוני תבור — עצים רחבים ומרווחים, לא יער נטוע.","long":"הגבעות האלה הן ממלכת אלון התבור. בניגוד ליערות האורנים שנטעה קק״ל, זה חורש טבעי: עצים רחבים ומרווחים, 'יער פארק', על קרקע רנדזינה בהירה שנוצרה מסלע הקירטון. אלון התבור משיר חלק מעליו בחורף — ולכן בסתיו הגבעות מקבלות גוון צהבהב-חום. לא כל עץ שרואים מהחלון הוא אלון תבור, אבל רוב העצים הגדולים והבודדים כאן — כן.","fact":"אלוני התבור העתיקים בארץ יכולים להגיע לגיל של מאות שנים. בגללם נקראה המועצה האזורית הסמוכה 'אלונה'.","cue":"בין צומת שפיה לבת שלמה, כשנראה חורש פתוח על הגבעות.","caution":"שני המסמכים — מימין. לא אומת. לא להצביע על עץ מסוים כאלון תבור."},"fr":{"script":"Un bois naturel de chênes du Tabor : de grands arbres espacés, pas une forêt plantée.","long":"Ces collines sont le royaume du chêne du Tabor. Contrairement aux forêts de pins plantées par le KKL, c'est un boisement naturel : de grands arbres espacés, une « forêt-parc », sur une terre claire, la rendzine, issue de la craie. Le chêne du Tabor perd une partie de ses feuilles en hiver : d'où les teintes jaune-brun des collines en automne. Tous les arbres ne sont pas des chênes du Tabor, mais la plupart des grands arbres isolés, oui.","fact":"Les vieux chênes du Tabor peuvent atteindre plusieurs siècles. Ce sont eux qui ont donné son nom au conseil régional voisin : Alona, de « alon », le chêne.","cue":"Entre le carrefour de Shfeya et Bat Shlomo, quand on voit un bois clair sur les collines.","caution":"Les deux documents disent à droite. Non vérifié. Ne pas désigner un arbre précis comme chêne du Tabor."},"en":{"script":"Natural Tabor-oak woodland — broad, widely spaced trees, not a planted forest.","long":"These hills are the kingdom of the Tabor oak. Unlike the pine forests planted by the JNF, this is natural woodland: big, widely spaced trees — a 'park forest' — on pale rendzina soil formed from chalk. The Tabor oak drops some of its leaves in winter, which is why the hills turn yellow-brown in autumn. Not every tree you see is a Tabor oak, but most of the big solitary ones are.","fact":"Old Tabor oaks can live for centuries. They gave the nearby regional council its name: Alona, from 'alon', oak.","cue":"Between Shfeya junction and Bat Shlomo, where open woodland covers the hills.","caution":"Both documents say right. Not verified. Don't point at a specific tree as a Tabor oak."},"ru":{"script":"Естественная роща таворских дубов — широкие, редко стоящие деревья, а не посаженный лес.","long":"Эти холмы — царство таворского дуба. В отличие от сосновых лесов, посаженных Еврейским национальным фондом, это естественное редколесье: крупные, далеко стоящие друг от друга деревья — «парковый лес» — на светлой почве рендзине, образовавшейся из мела. Зимой таворский дуб сбрасывает часть листьев, поэтому осенью холмы желтовато-бурые. Не каждое дерево за окном — таворский дуб, но большинство крупных одиночных деревьев — да.","fact":"Старые таворские дубы живут сотни лет. Они дали имя соседнему региональному совету — Алона, от «алон», дуб.","cue":"Между перекрёстком Шфея и Бат-Шломо, когда на холмах видно светлое редколесье.","caution":"В обоих документах — справа. Не проверено. Не называть конкретное дерево таворским дубом."}}$v3$::jsonb, $v3${"stop":"S7","final":false,"topic":"Alona oak woodland","docs":"יאיר: 'מצד ימין — יערות אלונה, יער אלונים טבעי עד הר חורשן'; מפנה צפוני: אלון מצוי ואלה; מפנה דרומי: אלון התבור ולבנה. יוסי: 'מצד ימין', חורש אלון התבור, קרטון ורנדזינה. אחרי אליקים: יערות אורן נטועים של קק״ל (לא טבעיים)."}$v3$::jsonb),
($v3$v3:ROAD67-10$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$למה מכסים לעיתים קרובות את מטעי השסק ברשתות?$v3$, $v3$["כדי להגן על הפרי מציפורים ומעטלפים","כדי לגדל בהם דגים","כדי לייצר שלג מלאכותי","כדי לשנות את צבע הפרי לכחול"]$v3$::jsonb, 0, $v3$פרי השסק המתוק מושך ציפורים ועטלפי פירות; הרשתות שומרות עליו עד הקטיף.$v3$, $v3$חקלאות$v3$, 2, 45, 6, $v3$הרשתות שומרות על הפרי — אחרת הציפורים והעטלפים אוכלים הכול לפנינו.$v3$, $v3$בעמקים לאורך הדרך גדלים מטעים — ובולט ביניהם השסק. השסק מבשיל באביב, כשיש מעט פירות אחרים, ולכן הוא מושך כל ציפור ועטלף פירות באזור. החקלאים פורשים רשתות מעל העצים — ככה גם לנו נשאר משהו לאכול. מסביב תראו גם כרמים וזיתים: האזור הזה מגדל פירות כבר מימי המושבות של הברון.$v3$, $v3$בעמק בין צומת שפיה לבת שלמה, אם רואים מטעים מכוסים ברשתות.$v3$, $v3$יאיר: מטעים — בולטים שסק, אפרסקים, שזיפים ורימונים, כרמים וזיתים. יוסי: 'מצד ימין בעמק מטעי שסק' מכוסים ברשתות בגלל ציפורים ועטלפים. לא אומת איפה בדיוק נראים מטעים מכוסים.$v3$, $v3$[{"title":"שסק יפני — ויקיפדיה","url":"https://he.wikipedia.org/wiki/שסק_יפני"}]$v3$::jsonb, $v3$עטלף הפירות המצוי יכול לעוף עשרות קילומטרים בלילה אחד כדי להגיע למטע — ממש משלוח עד הבית.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Pourquoi couvre-t-on souvent les vergers de néfliers de filets ?","options":["Pour protéger les fruits des oiseaux et des chauves-souris","Pour y élever des poissons","Pour fabriquer de la neige artificielle","Pour rendre les fruits bleus"],"explanation":"La nèfle sucrée attire les oiseaux et les roussettes ; les filets la protègent jusqu'à la récolte.","category":"Agriculture"},"en":{"text":"Why are loquat orchards often covered with nets?","options":["To protect the fruit from birds and bats","To farm fish in them","To make artificial snow","To turn the fruit blue"],"explanation":"Sweet loquats attract birds and fruit bats; the nets protect them until harvest.","category":"Agriculture"},"ru":{"text":"Зачем сады мушмулы часто накрывают сетками?","options":["Чтобы защитить плоды от птиц и летучих мышей","Чтобы разводить в них рыбу","Чтобы делать искусственный снег","Чтобы плоды стали синими"],"explanation":"Сладкая мушмула привлекает птиц и крыланов; сетки сохраняют урожай до сбора.","category":"Сельское хозяйство"}}$v3$::jsonb, $v3${"he":{"script":"הרשתות שומרות על הפרי — אחרת הציפורים והעטלפים אוכלים הכול לפנינו.","long":"בעמקים לאורך הדרך גדלים מטעים — ובולט ביניהם השסק. השסק מבשיל באביב, כשיש מעט פירות אחרים, ולכן הוא מושך כל ציפור ועטלף פירות באזור. החקלאים פורשים רשתות מעל העצים — ככה גם לנו נשאר משהו לאכול. מסביב תראו גם כרמים וזיתים: האזור הזה מגדל פירות כבר מימי המושבות של הברון.","fact":"עטלף הפירות המצוי יכול לעוף עשרות קילומטרים בלילה אחד כדי להגיע למטע — ממש משלוח עד הבית.","cue":"בעמק בין צומת שפיה לבת שלמה, אם רואים מטעים מכוסים ברשתות.","caution":"מסמך יוסי — מימין. לא אומת. לשאול רק אם אכן רואים רשתות מהחלון."},"fr":{"script":"Les filets protègent les fruits : sinon les oiseaux et les chauves-souris mangent tout avant nous.","long":"Dans les vallons, le long de la route, poussent des vergers, notamment de néfliers du Japon. La nèfle mûrit au printemps, quand il y a peu d'autres fruits : elle attire donc tous les oiseaux et chauves-souris frugivores du coin. Les agriculteurs tendent des filets au-dessus des arbres — pour qu'il en reste un peu pour nous. Autour, vous verrez aussi des vignes et des oliviers : on cultive des fruits ici depuis l'époque des colonies du Baron.","fact":"La roussette d'Égypte peut parcourir des dizaines de kilomètres en une nuit pour atteindre un verger : une vraie livraison à domicile.","cue":"Dans la vallée entre le carrefour de Shfeya et Bat Shlomo, si l'on voit des vergers sous filets.","caution":"Document de Yossi : à droite. Non vérifié. Ne poser la question que si l'on voit vraiment des filets."},"en":{"script":"The nets protect the fruit — otherwise the birds and bats eat it all before we do.","long":"In the little valleys along the road grow orchards — loquats stand out among them. Loquats ripen in spring, when few other fruits are around, so they attract every bird and fruit bat in the area. Farmers stretch nets over the trees so there's something left for us. You'll also see vineyards and olive groves: fruit has been grown here since the days of the Baron's colonies.","fact":"The Egyptian fruit bat can fly dozens of kilometres in a single night to reach an orchard — true home delivery.","cue":"In the valley between Shfeya junction and Bat Shlomo, if netted orchards are visible.","caution":"Yossi's notes: on the right. Not verified. Ask only if nets are actually visible."},"ru":{"script":"Сетки берегут плоды — иначе птицы и летучие мыши съедят всё раньше нас.","long":"В долинах вдоль дороги растут сады, и среди них выделяется японская мушмула. Она созревает весной, когда других фруктов мало, и поэтому привлекает всех птиц и плодоядных летучих мышей в округе. Фермеры натягивают над деревьями сетки — чтобы и нам что-то осталось. Вокруг вы увидите и виноградники, и оливы: фрукты здесь выращивают ещё со времён колоний барона.","fact":"Египетский крылан может пролететь за ночь десятки километров, чтобы добраться до сада, — настоящая доставка на дом.","cue":"В долине между перекрёстком Шфея и Бат-Шломо, если видны сады под сетками.","caution":"У Йоси — справа. Не проверено. Задавать вопрос, только если сетки действительно видны."}}$v3$::jsonb, $v3${"stop":"S10","final":false,"topic":"Loquat orchards","docs":"יאיר: מטעים — בולטים שסק, אפרסקים, שזיפים ורימונים, כרמים וזיתים. יוסי: 'מצד ימין בעמק מטעי שסק' מכוסים ברשתות בגלל ציפורים ועטלפים. לא אומת איפה בדיוק נראים מטעים מכוסים."}$v3$::jsonb),
($v3$v3:ROAD67-03$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$המושבה בת שלמה (1889) נקראה על שם —$v3$, $v3$["אמו של הברון רוטשילד, בתו של שלמה רוטשילד","בתו של המלך שלמה","אשתו של הרצל","התינוקת הראשונה שנולדה במושבה"]$v3$::jsonb, 0, $v3$השם מכבד את בטי (בתיה) רוטשילד — אמו של הברון אדמונד דה רוטשילד ובתו של שלמה (סלומון) רוטשילד. המושבה נוסדה ב-1889.$v3$, $v3$היסטוריה$v3$, 2, 45, 7, $v3$נוסדה ב-1889, על שם אמו של הברון — בתו של שלמה רוטשילד.$v3$, $v3$אנחנו ליד בת שלמה — מהמושבות הקטנות של הברון רוטשילד, שנוסדה ב-1889. השם הוא מחווה משפחתית: אמו של הברון, בטי, הייתה בתו של שלמה רוטשילד — ומכאן 'בת שלמה'. הרחוב הראשי שומר עד היום על בתי האבן של המושבה הוותיקה, ומסביב כרמים, מטעים וחורש של אלוני תבור. זו מושבה קטנה מאוד — וזה בדיוק מה ששמר על הקסם שלה.$v3$, $v3$כ-8 ק״מ, באזור מחלף בת שלמה.$v3$, $v3$יאיר: 'מצד ימין', מושבת ברון מ-1889, 'אחרי קום המדינה הוקם גם מושב של עולי אירופה' (לא אומת — לא נכלל). יוסי: 'מימין ומשמאל — המושבה מימין', על שם בטי, בת שלמה רוטשילד, אמו של הברון; רחוב ראשי בשימור. מחלף בת שלמה: 32.598, 35.005 (ויקיפדיה).$v3$, $v3$[{"title":"Bat Shlomo — Wikipedia","url":"https://en.wikipedia.org/wiki/Bat_Shlomo"},{"title":"מחלף בת שלמה — ויקיפדיה","url":"https://he.wikipedia.org/wiki/מחלף_בת_שלמה"}]$v3$::jsonb, $v3$באזור הזה מסתתרים שלושה דורות של רוטשילדים: זכרון יעקב על שם אביו של הברון (ג'יימס-יעקב), מאיר שפיה על שם סבו, ובת שלמה על שם אמו.$v3$, $v3$check$v3$, $v3${"fr":{"text":"La colonie de Bat Shlomo (1889) doit son nom à…","options":["La mère du baron de Rothschild, fille de Salomon de Rothschild","La fille du roi Salomon","L'épouse de Herzl","Le premier bébé né dans la colonie"],"explanation":"Le nom honore Betty de Rothschild, mère du baron Edmond de Rothschild et fille de Salomon (Shlomo) de Rothschild. La colonie a été fondée en 1889.","category":"Histoire"},"en":{"text":"The colony of Bat Shlomo (1889) is named after —","options":["The Baron de Rothschild's mother, daughter of Salomon Rothschild","King Solomon's daughter","Herzl's wife","The first baby born in the colony"],"explanation":"The name honours Betty de Rothschild — mother of Baron Edmond de Rothschild and daughter of Salomon (Shlomo) Rothschild. The colony was founded in 1889.","category":"History"},"ru":{"text":"Колония Бат-Шломо (1889) названа в честь…","options":["Матери барона Ротшильда, дочери Соломона Ротшильда","Дочери царя Соломона","Жены Герцля","Первого ребёнка, родившегося в колонии"],"explanation":"Название в честь Бетти Ротшильд — матери барона Эдмона де Ротшильда и дочери Соломона (Шломо) Ротшильда. Колония основана в 1889 году.","category":"История"}}$v3$::jsonb, $v3${"he":{"script":"נוסדה ב-1889, על שם אמו של הברון — בתו של שלמה רוטשילד.","long":"אנחנו ליד בת שלמה — מהמושבות הקטנות של הברון רוטשילד, שנוסדה ב-1889. השם הוא מחווה משפחתית: אמו של הברון, בטי, הייתה בתו של שלמה רוטשילד — ומכאן 'בת שלמה'. הרחוב הראשי שומר עד היום על בתי האבן של המושבה הוותיקה, ומסביב כרמים, מטעים וחורש של אלוני תבור. זו מושבה קטנה מאוד — וזה בדיוק מה ששמר על הקסם שלה.","fact":"באזור הזה מסתתרים שלושה דורות של רוטשילדים: זכרון יעקב על שם אביו של הברון (ג'יימס-יעקב), מאיר שפיה על שם סבו, ובת שלמה על שם אמו.","cue":"כ-8 ק״מ, באזור מחלף בת שלמה.","caution":"הצד לא אומת: מסמך יאיר — מימין; מסמך יוסי — 'מימין ומשמאל' (המושבה מימין). לא להצביע עד אימות."},"fr":{"script":"Fondée en 1889, elle porte le nom de la mère du Baron, fille de Salomon de Rothschild.","long":"Nous passons près de Bat Shlomo, l'une des petites colonies du baron de Rothschild, fondée en 1889. Le nom est un hommage familial : la mère du Baron, Betty, était la fille de Salomon de Rothschild — d'où « Bat Shlomo », « la fille de Salomon ». La rue principale garde ses maisons de pierre d'origine, entourées de vignes, de vergers et de chênes du Tabor. Une toute petite colonie, et c'est justement ce qui a préservé son charme.","fact":"Trois générations de Rothschild se cachent dans le paysage : Zikhron Yaakov porte le nom du père du Baron (James-Yaakov), Meir Shfeya celui de son grand-père, et Bat Shlomo celui de sa mère.","cue":"Vers le km 8, à l'échangeur de Bat Shlomo.","caution":"Côté non vérifié : document de Yaïr — à droite ; document de Yossi — « des deux côtés » (la colonie à droite). Ne pas montrer avant vérification."},"en":{"script":"Founded in 1889 and named after the Baron's mother, Salomon Rothschild's daughter.","long":"We're passing Bat Shlomo, one of Baron de Rothschild's small colonies, founded in 1889. The name is a family tribute: the Baron's mother, Betty, was the daughter of Salomon Rothschild — hence 'Bat Shlomo', 'Shlomo's daughter'. The main street still keeps the original stone houses, surrounded by vineyards, orchards and Tabor oaks. It's a tiny colony — and that's exactly what kept its charm.","fact":"Three generations of Rothschilds hide in this landscape: Zikhron Ya'akov is named after the Baron's father (James-Yaakov), Meir Shfeya after his grandfather, and Bat Shlomo after his mother.","cue":"Around km 8, at the Bat Shlomo interchange.","caution":"Side not verified: Yair's notes — right; Yossi's notes — 'both sides' (the colony on the right). Don't point until checked."},"ru":{"script":"Основана в 1889 году и названа в честь матери барона — дочери Соломона Ротшильда.","long":"Мы проезжаем Бат-Шломо — одну из маленьких колоний барона Ротшильда, основанную в 1889 году. Название — семейный жест: мать барона, Бетти, была дочерью Соломона Ротшильда, отсюда «Бат-Шломо» — «дочь Шломо». Главная улица до сих пор хранит старые каменные дома, вокруг виноградники, сады и рощи таворского дуба. Колония совсем крошечная — именно поэтому она сохранила своё очарование.","fact":"В этом пейзаже спрятаны три поколения Ротшильдов: Зихрон-Яаков назван в честь отца барона (Джеймса-Яакова), Меир-Шфея — в честь деда, а Бат-Шломо — в честь матери.","cue":"Около 8-го км, у развязки Бат-Шломо.","caution":"Сторона не проверена: у Яира — справа; у Йоси — «с обеих сторон» (колония справа). Не показывать до проверки."}}$v3$::jsonb, $v3${"stop":"S3","final":false,"topic":"Bat Shlomo","docs":"יאיר: 'מצד ימין', מושבת ברון מ-1889, 'אחרי קום המדינה הוקם גם מושב של עולי אירופה' (לא אומת — לא נכלל). יוסי: 'מימין ומשמאל — המושבה מימין', על שם בטי, בת שלמה רוטשילד, אמו של הברון; רחוב ראשי בשימור. מחלף בת שלמה: 32.598, 35.005 (ויקיפדיה)."}$v3$::jsonb),
($v3$v3:ROAD67-09$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$מדוע הגבעות לאורך הדרך רכות ומעוגלות ולא חדות?$v3$, $v3$["בליה וסחיפה של סלעי קירטון רכים יחסית","התפרצות געשית לפני כמה מאות שנים","חפירות של בני אדם","קרחונים שעדיין קיימים כאן"]$v3$::jsonb, 0, $v3$קירטון הוא סלע גירי רך יחסית; במשך מיליוני שנים הבליה והסחיפה עיגלו את הגבעות.$v3$, $v3$גאולוגיה$v3$, 2, 45, 8, $v3$הגבעות עגולות כי הן מקירטון — סלע רך מקרקעית ים עתיקה.$v3$, $v3$תסתכלו על הגבעות: אין כאן צוקים חדים, רק גבעות רכות ומעוגלות. הסיבה — הסלע. רוב האזור בנוי מקירטון, סלע גירי רך שנוצר בקרקעית ים מיליארדי שלדים זעירים של יצורים ימיים. גשם ורוח שוחקים אותו בקלות, וכך במשך מיליוני שנים הגבעות התעגלו. בחתכי הדרך אפשר לראות לפעמים פסים כהים של צור — סלע קשה מאוד, ממנו עשו בני האדם הקדמונים כלים.$v3$, $v3$בעלייה במעלה נחל תות / באזור חתכי הדרך. אפשר לשאול בכל מקום על כביש 67.$v3$, $v3$יאיר: גבעות רכות ומעוגלות מקירטון רך, בליה וסחיפה. יוסי: 'צד ימין — שכבות סלע קרטון וצור לחלופין' (חתך דרך אחרי עין תות), פלנקטון בעל שלד גיר (חורריות) ובעל שלד צורן (רדיולריות). לא אומת איזה חתך דרך נראה.$v3$, $v3$[{"title":"רמות מנשה — ויקיפדיה","url":"https://he.wikipedia.org/wiki/רמות_מנשה"}]$v3$::jsonb, $v3$הקירטון הוא בעצם 'בית קברות' של יצורים ימיים מיקרוסקופיים — הוכחה לכך שכל האזור הזה היה פעם קרקעית ים.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Pourquoi les collines le long de la route sont-elles douces et arrondies plutôt qu'escarpées ?","options":["L'érosion de roches crayeuses assez tendres","Une éruption volcanique il y a quelques siècles","Des fouilles humaines","Des glaciers encore présents ici"],"explanation":"La craie est une roche calcaire assez tendre : en quelques millions d'années, l'altération et l'érosion ont arrondi les collines.","category":"Géologie"},"en":{"text":"Why are the hills along the road soft and rounded rather than sharp?","options":["Weathering and erosion of relatively soft chalk","A volcanic eruption a few centuries ago","Human digging","Glaciers that still exist here"],"explanation":"Chalk is a fairly soft limestone; over millions of years weathering and erosion rounded the hills.","category":"Geology"},"ru":{"text":"Почему холмы вдоль дороги мягкие и округлые, а не острые?","options":["Выветривание и эрозия сравнительно мягкого мела","Извержение вулкана несколько веков назад","Раскопки, сделанные людьми","Ледники, которые здесь до сих пор есть"],"explanation":"Мел — довольно мягкая известковая порода; за миллионы лет выветривание и эрозия скруглили холмы.","category":"Геология"}}$v3$::jsonb, $v3${"he":{"script":"הגבעות עגולות כי הן מקירטון — סלע רך מקרקעית ים עתיקה.","long":"תסתכלו על הגבעות: אין כאן צוקים חדים, רק גבעות רכות ומעוגלות. הסיבה — הסלע. רוב האזור בנוי מקירטון, סלע גירי רך שנוצר בקרקעית ים מיליארדי שלדים זעירים של יצורים ימיים. גשם ורוח שוחקים אותו בקלות, וכך במשך מיליוני שנים הגבעות התעגלו. בחתכי הדרך אפשר לראות לפעמים פסים כהים של צור — סלע קשה מאוד, ממנו עשו בני האדם הקדמונים כלים.","fact":"הקירטון הוא בעצם 'בית קברות' של יצורים ימיים מיקרוסקופיים — הוכחה לכך שכל האזור הזה היה פעם קרקעית ים.","cue":"בעלייה במעלה נחל תות / באזור חתכי הדרך. אפשר לשאול בכל מקום על כביש 67.","caution":"לא אומת באיזה צד וכמה ברור נראה חתך הדרך. לא להבטיח שכבות צור."},"fr":{"script":"Les collines sont rondes parce qu'elles sont en craie, une roche tendre née au fond d'une mer ancienne.","long":"Regardez les collines : pas de falaises abruptes, seulement des formes douces et arrondies. La raison, c'est la roche. La région est surtout faite de craie, une roche calcaire tendre formée au fond de la mer par des milliards de minuscules squelettes d'organismes marins. La pluie et le vent l'usent facilement : en quelques millions d'années, les collines se sont arrondies. Dans les tranchées de la route, on voit parfois des bandes sombres de silex, une roche très dure dont les hommes préhistoriques faisaient leurs outils.","fact":"La craie est en réalité un « cimetière » de micro-organismes marins : la preuve que toute la région était autrefois un fond de mer.","cue":"Dans la montée le long du Nahal Tut / près des tranchées de la route. Utilisable partout sur la route 67.","caution":"Côté et netteté des tranchées non vérifiés. Ne pas promettre de bandes de silex."},"en":{"script":"The hills are round because they're chalk — a soft rock from an ancient seabed.","long":"Look at the hills: no sharp cliffs, just soft, rounded shapes. The reason is the rock. Most of the area is chalk, a soft limestone formed on the seabed from billions of tiny skeletons of marine creatures. Rain and wind wear it down easily, so over millions of years the hills became rounded. In the road cuts you can sometimes see dark bands of flint — a very hard rock that prehistoric people used for tools.","fact":"Chalk is really a 'graveyard' of microscopic sea creatures — proof that this whole area was once the bottom of the sea.","cue":"On the climb along Nahal Tut / near the road cuts. Usable anywhere on Road 67.","caution":"Side and clarity of the road cuts not verified. Don't promise flint bands."},"ru":{"script":"Холмы круглые, потому что они из мела — мягкой породы со дна древнего моря.","long":"Посмотрите на холмы: никаких острых скал, только мягкие округлые формы. Причина — в породе. Район сложен в основном мелом — мягким известняком, который образовался на морском дне из миллиардов крошечных скелетов морских организмов. Дождь и ветер легко его стирают, и за миллионы лет холмы скруглились. В дорожных выемках иногда видны тёмные полосы кремня — очень твёрдой породы, из которой древние люди делали орудия.","fact":"Мел — это, по сути, «кладбище» микроскопических морских существ: доказательство того, что весь этот район когда-то был морским дном.","cue":"На подъёме вдоль ручья Тут / у дорожных выемок. Подходит для любого места на шоссе 67.","caution":"Сторона и видимость выемок не проверены. Не обещать полосы кремня."}}$v3$::jsonb, $v3${"stop":"S9","final":false,"topic":"Ramat Menashe geology","docs":"יאיר: גבעות רכות ומעוגלות מקירטון רך, בליה וסחיפה. יוסי: 'צד ימין — שכבות סלע קרטון וצור לחלופין' (חתך דרך אחרי עין תות), פלנקטון בעל שלד גיר (חורריות) ובעל שלד צורן (רדיולריות). לא אומת איזה חתך דרך נראה."}$v3$::jsonb),
($v3$v3:ROAD67-14$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$הכרמל ורמות מנשה, משני צדי הכביש, הוכרזו על ידי אונסק״ו כ…$v3$, $v3$["שמורות ביוספרה","שמורות מדבר","פארקים ימיים","אתרי סקי"]$v3$::jsonb, 0, $v3$הכרמל (1996) ורמות מנשה (2011) הם שמורות ביוספרה של אונסק״ו — אזורים שבהם לומדים איך אנשים וטבע חיים יחד.$v3$, $v3$טבע וסביבה$v3$, 2, 45, 9, $v3$שתיהן שמורות ביוספרה של אונסק״ו — אנשים וטבע חיים יחד.$v3$, $v3$תסתכלו מסביב: משני צדי הכביש יש שני אזורים מיוחדים בעיני העולם. הכרמל מצפון ורמות מנשה מדרום הוכרזו על ידי אונסק״ו כשמורות ביוספרה. זה לא אומר שאסור לגור בהם — להפך: בשמורת ביוספרה בודקים איך אפשר לחיות, לגדל פרות, מטעים וכרמים, ובכל זאת לשמור על החורש, על הנחלים ועל בעלי החיים. הכביש שלנו עובר בדיוק בגבול שביניהם.$v3$, $v3$בקטע האחרון של כביש 67, לפני עין תות — הכרמל משמאל, רמות מנשה מימין (לפי הגאוגרפיה; הצד לא אומת).$v3$, $v3$לא מופיע במסמכים. מקור: UNESCO — שמורת הביוספרה הר הכרמל (1996) ושמורת הביוספרה רמות מנשה (2011). הכביש עובר בין שני האזורים.$v3$, $v3$[{"title":"UNESCO — Ramot Menashe Biosphere Reserve","url":"https://www.unesco.org/en/mab/ramot-menashe"},{"title":"UNESCO — Mount Carmel Biosphere Reserve","url":"https://www.unesco.org/en/mab/mount-carmel"}]$v3$::jsonb, $v3$ברמות מנשה רועים עדרי בקר בין אלוני התבור — הבקר עוזר למנוע שריפות, כי הוא אוכל את העשב היבש.$v3$, $v3$topic$v3$, $v3${"fr":{"text":"Le Carmel et les collines de Menashe, de part et d'autre de la route, ont été classés par l'UNESCO comme…","options":["Réserves de biosphère","Réserves désertiques","Parcs marins","Stations de ski"],"explanation":"Le Carmel (1996) et les collines de Menashe (2011) sont des réserves de biosphère de l'UNESCO : des territoires où l'on apprend à faire vivre ensemble l'homme et la nature.","category":"Nature et environnement"},"en":{"text":"Mount Carmel and the Menashe Heights, on either side of the road, were designated by UNESCO as…","options":["Biosphere reserves","Desert reserves","Marine parks","Ski resorts"],"explanation":"Mount Carmel (1996) and the Menashe Heights (2011) are UNESCO biosphere reserves — areas where people learn how humans and nature can live together.","category":"Nature and environment"},"ru":{"text":"Кармель и возвышенность Менаше по обе стороны дороги ЮНЕСКО объявила…","options":["биосферными заповедниками","пустынными заповедниками","морскими парками","горнолыжными курортами"],"explanation":"Кармель (1996) и Менаше (2011) — биосферные заповедники ЮНЕСКО: территории, где учатся тому, как человеку и природе жить вместе.","category":"Природа"}}$v3$::jsonb, $v3${"he":{"script":"שתיהן שמורות ביוספרה של אונסק״ו — אנשים וטבע חיים יחד.","long":"תסתכלו מסביב: משני צדי הכביש יש שני אזורים מיוחדים בעיני העולם. הכרמל מצפון ורמות מנשה מדרום הוכרזו על ידי אונסק״ו כשמורות ביוספרה. זה לא אומר שאסור לגור בהם — להפך: בשמורת ביוספרה בודקים איך אפשר לחיות, לגדל פרות, מטעים וכרמים, ובכל זאת לשמור על החורש, על הנחלים ועל בעלי החיים. הכביש שלנו עובר בדיוק בגבול שביניהם.","fact":"ברמות מנשה רועים עדרי בקר בין אלוני התבור — הבקר עוזר למנוע שריפות, כי הוא אוכל את העשב היבש.","cue":"בקטע האחרון של כביש 67, לפני עין תות — הכרמל משמאל, רמות מנשה מימין (לפי הגאוגרפיה; הצד לא אומת).","caution":"לא מופיע במסמכי ההדרכה — המקור הוא אונסק״ו. לא להצביע על גבול מסוים."},"fr":{"script":"Ce sont deux réserves de biosphère de l'UNESCO : l'homme et la nature y vivent ensemble.","long":"Regardez autour de vous : de chaque côté de la route, deux territoires reconnus par le monde entier. Le Carmel au nord et les collines de Menashe au sud sont des réserves de biosphère de l'UNESCO. Cela ne veut pas dire qu'on n'a pas le droit d'y vivre, au contraire : on y cherche comment habiter, élever des vaches, cultiver vergers et vignes, tout en protégeant les bois, les ruisseaux et les animaux. Notre route passe exactement à la frontière entre les deux.","fact":"Dans les collines de Menashe, des troupeaux de vaches pâturent entre les chênes du Tabor : elles aident à prévenir les incendies en mangeant l'herbe sèche.","cue":"Sur la dernière partie de la route 67, avant Ein Tut : le Carmel à gauche, Menashe à droite (d'après la géographie ; côté non vérifié).","caution":"Absent des documents de guidage : la source est l'UNESCO. Ne pas désigner de frontière précise."},"en":{"script":"Both are UNESCO biosphere reserves — people and nature living together.","long":"Look around: on both sides of the road are two areas recognised by the whole world. Mount Carmel to the north and the Menashe Heights to the south are UNESCO biosphere reserves. That doesn't mean nobody may live there — quite the opposite: they test how people can live, raise cattle and grow orchards and vineyards while still protecting the woodland, the streams and the animals. Our road runs right along the border between them.","fact":"In the Menashe Heights, herds of cattle graze among the Tabor oaks — they help prevent fires by eating the dry grass.","cue":"On the last stretch of Road 67 before Ein Tut: Carmel on the left, Menashe on the right (by geography; side not verified).","caution":"Not in the guide documents — the source is UNESCO. Don't point at a specific boundary."},"ru":{"script":"Оба района — биосферные заповедники ЮНЕСКО: человек и природа живут вместе.","long":"Посмотрите вокруг: по обе стороны дороги — две территории, признанные всем миром. Кармель на севере и возвышенность Менаше на юге — биосферные заповедники ЮНЕСКО. Это не значит, что жить там запрещено, наоборот: здесь ищут способ жить, разводить коров, выращивать сады и виноградники и при этом беречь леса, ручьи и животных. Наша дорога проходит как раз по границе между ними.","fact":"На возвышенности Менаше среди таворских дубов пасутся стада коров — они помогают предотвращать пожары, поедая сухую траву.","cue":"На последнем участке шоссе 67 перед Эйн-Тутом: Кармель слева, Менаше справа (по географии; сторона не проверена).","caution":"Этого нет в документах гидов — источник ЮНЕСКО. Не показывать конкретную границу."}}$v3$::jsonb, $v3${"stop":"S14","final":false,"topic":"Biosphere reserves","docs":"לא מופיע במסמכים. מקור: UNESCO — שמורת הביוספרה הר הכרמל (1996) ושמורת הביוספרה רמות מנשה (2011). הכביש עובר בין שני האזורים."}$v3$::jsonb),
($v3$v3:ROAD67-04$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$תחנת הכוח חגית, ליד מחלף עין תות, מייצרת חשמל בעיקר מ…$v3$, $v3$["פחם","רוח","גז טבעי","אנרגיה גרעינית"]$v3$::jsonb, 2, $v3$חגית היא תחנת כוח שפועלת בעיקר על גז טבעי, עם סולר כגיבוי.$v3$, $v3$אנרגיה$v3$, 2, 45, 10, $v3$תחנת הכוח עובדת על גז טבעי מהים התיכון. מכאן — כביש 6 בלי אגרה.$v3$, $v3$אנחנו מגיעים למחלף עין תות — כאן נגמר כביש 67 וממשיכים צפונה בכביש 6, בקטע שאין בו אגרה עד יקנעם. בסביבה נמצאת תחנת הכוח חגית. היא שורפת בעיקר גז טבעי שמגיע ממאגרי הגז בים התיכון, ומסובבת טורבינות שמייצרות חשמל. בטורבינות 'מחזור משולב' מנצלים גם את החום של גזי הפליטה כדי לייצר קיטור ולסובב טורבינה נוספת — יותר חשמל מאותה כמות דלק.$v3$, $v3$בהתקרבות למחלף עין תות, סוף כביש 67. לא להצביע על ארובה מסוימת.$v3$, $v3$יאיר: 'מצד שמאל', מופעלת בגז, שמה שונה לתחנת הכוח דוד לוי (דצמבר 2024), חגית מזרח נמכרה ונקראת 'אורות פנינה' — לא אומת. יוסי: 'משמאל'; הערת הבודק בסוף המסמך: 'תחנת הכוח — הארובות מימין'. התחנה: 32.617, 35.043 (GEO/Wikidata) — צפון-מערבית למחלף עין תות (32.610, 35.048).$v3$, $v3$[{"title":"Hagit power station — Global Energy Monitor","url":"https://www.gem.wiki/Hagit_power_station"},{"title":"מחלף עין תות — ויקיפדיה","url":"https://he.wikipedia.org/wiki/מחלף_עין_תות"}]$v3$::jsonb, $v3$'עין תות' — על שם המעיין שמצפון למחלף. ומתחת לתחנת הכוח נובעת סדרת מעיינות של נחל תות: חשמל וטבע במרחק של כמה מאות מטרים.$v3$, $v3$check$v3$, $v3${"fr":{"text":"La centrale électrique de Hagit, près de l'échangeur d'Ein Tut, produit surtout son électricité à partir…","options":["du charbon","du vent","du gaz naturel","du nucléaire"],"explanation":"Hagit fonctionne principalement au gaz naturel, avec du gazole en secours.","category":"Énergie"},"en":{"text":"The Hagit power station, near the Ein Tut interchange, makes electricity mainly from…","options":["Coal","Wind","Natural gas","Nuclear power"],"explanation":"Hagit runs mainly on natural gas, with diesel as a backup.","category":"Energy"},"ru":{"text":"Электростанция Хагит у развязки Эйн-Тут вырабатывает электричество в основном из…","options":["угля","ветра","природного газа","ядерной энергии"],"explanation":"Хагит работает в основном на природном газе, дизельное топливо — резервное.","category":"Энергетика"}}$v3$::jsonb, $v3${"he":{"script":"תחנת הכוח עובדת על גז טבעי מהים התיכון. מכאן — כביש 6 בלי אגרה.","long":"אנחנו מגיעים למחלף עין תות — כאן נגמר כביש 67 וממשיכים צפונה בכביש 6, בקטע שאין בו אגרה עד יקנעם. בסביבה נמצאת תחנת הכוח חגית. היא שורפת בעיקר גז טבעי שמגיע ממאגרי הגז בים התיכון, ומסובבת טורבינות שמייצרות חשמל. בטורבינות 'מחזור משולב' מנצלים גם את החום של גזי הפליטה כדי לייצר קיטור ולסובב טורבינה נוספת — יותר חשמל מאותה כמות דלק.","fact":"'עין תות' — על שם המעיין שמצפון למחלף. ומתחת לתחנת הכוח נובעת סדרת מעיינות של נחל תות: חשמל וטבע במרחק של כמה מאות מטרים.","cue":"בהתקרבות למחלף עין תות, סוף כביש 67. לא להצביע על ארובה מסוימת.","caution":"צד לא אומת: שני המסמכים — משמאל; הערת הבודק במסמך יוסי — 'הארובות מימין'. לפי הקואורדינטות התחנה צפון-מערבית למחלף. שם חדש ('דוד לוי') ומכירת 'חגית מזרח' — לפי מסמך יאיר בלבד, לא אומת."},"fr":{"script":"La centrale fonctionne au gaz naturel de la Méditerranée. À partir d'ici : la route 6, sans péage.","long":"Nous arrivons à l'échangeur d'Ein Tut : ici se termine la route 67, et nous continuons vers le nord sur la route 6, sur la section gratuite jusqu'à Yokneam. Tout près se trouve la centrale de Hagit. Elle brûle surtout du gaz naturel venu des gisements de la Méditerranée et fait tourner des turbines. Dans le « cycle combiné », la chaleur des gaz d'échappement produit aussi de la vapeur qui entraîne une seconde turbine : plus d'électricité avec le même combustible.","fact":"« Ein Tut », « la source du mûrier », doit son nom à une source au nord de l'échangeur. Et sous la centrale jaillissent les sources du Nahal Tut : énergie et nature à quelques centaines de mètres.","cue":"À l'approche de l'échangeur d'Ein Tut, fin de la route 67. Ne pas désigner une cheminée précise.","caution":"Côté non vérifié : les deux documents disent à gauche ; la note de relecture du document de Yossi dit « les cheminées à droite ». D'après les coordonnées, la centrale est au nord-ouest de l'échangeur. Nouveau nom (« David Lévy ») et vente de « Hagit Est » : seulement dans le document de Yaïr, non vérifiés."},"en":{"script":"The power station runs on natural gas from the Mediterranean. From here: Road 6, toll-free.","long":"We're reaching the Ein Tut interchange: Road 67 ends here and we continue north on Road 6, on the toll-free section to Yokneam. Close by is the Hagit power station. It burns mostly natural gas from the Mediterranean gas fields and spins turbines that generate electricity. In 'combined-cycle' units the heat of the exhaust gases also makes steam that drives a second turbine — more electricity from the same fuel.","fact":"'Ein Tut' — 'the mulberry spring' — is named after a spring north of the interchange. And below the power station rise the springs of Nahal Tut: power and nature a few hundred metres apart.","cue":"Approaching the Ein Tut interchange, the end of Road 67. Don't point at a specific chimney.","caution":"Side not verified: both documents say left; the reviewer's note in Yossi's document says 'chimneys on the right'. By coordinates the plant is north-west of the interchange. New name ('David Levy') and the sale of 'Hagit East': only in Yair's notes, not verified."},"ru":{"script":"Электростанция работает на природном газе из Средиземного моря. Дальше — шоссе 6 без оплаты.","long":"Мы подъезжаем к развязке Эйн-Тут: здесь заканчивается шоссе 67, и дальше мы едем на север по шоссе 6, по бесплатному участку до Йокнеама. Рядом находится электростанция Хагит. Она сжигает в основном природный газ с месторождений в Средиземном море и вращает турбины. В установках «комбинированного цикла» тепло выхлопных газов ещё и превращает воду в пар, который крутит вторую турбину: больше электричества из того же топлива.","fact":"«Эйн-Тут» — «тутовый источник» — назван по роднику к северу от развязки. А под электростанцией бьют родники ручья Тут: энергетика и природа в нескольких сотнях метров друг от друга.","cue":"При подъезде к развязке Эйн-Тут, в конце шоссе 67. Не указывать на конкретную трубу.","caution":"Сторона не проверена: в обоих документах — слева; в пометке проверяющего у Йоси — «трубы справа». По координатам станция северо-западнее развязки. Новое название («Давид Леви») и продажа «Хагит-Восток» — только в записях Яира, не проверено."}}$v3$::jsonb, $v3${"stop":"S4","final":false,"topic":"Hagit power station","docs":"יאיר: 'מצד שמאל', מופעלת בגז, שמה שונה לתחנת הכוח דוד לוי (דצמבר 2024), חגית מזרח נמכרה ונקראת 'אורות פנינה' — לא אומת. יוסי: 'משמאל'; הערת הבודק בסוף המסמך: 'תחנת הכוח — הארובות מימין'. התחנה: 32.617, 35.043 (GEO/Wikidata) — צפון-מערבית למחלף עין תות (32.610, 35.048)."}$v3$::jsonb),
($v3$v3:ROAD67-13$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$כביש 6, 'כביש חוצה ישראל', נקרא על שם —$v3$, $v3$["יצחק רבין","דוד בן-גוריון","מנחם בגין","גולדה מאיר"]$v3$::jsonb, 0, $v3$כביש 6 נקרא 'דרך יצחק רבין', על שם ראש הממשלה שנרצח ב-1995.$v3$, $v3$ישראל היום$v3$, 2, 45, 11, $v3$״דרך יצחק רבין״ — הכביש הארוך בישראל, בלי קופות: מצלמות.$v3$, $v3$עכשיו עלינו על כביש 6 — כביש חוצה ישראל, שנקרא על שם ראש הממשלה יצחק רבין. זה הכביש הארוך במדינה: מאזור באר שבע בדרום ועד אזור קריית אתא בצפון. רוב הכביש הוא כביש אגרה עם מצלמות במקום קופות, אבל הקטע שאנחנו נוסעים בו עכשיו, מעין תות ליקנעם, הוא בחינם. פעם זה היה כביש 70 צר, והוא הורחב לארבעה נתיבים לכל כיוון.$v3$, $v3$אחרי מחלף עין תות, כשעולים על כביש 6 צפונה.$v3$, $v3$יאיר: מתחברים לכביש 6, כביש יצחק רבין, ראש הממשלה החמישי; מתחיל בצומת שוקת ומסתיים במחלף אלונים. יוסי: כביש אגרה; 'כביש 6 צפון נקרא על שם יצחק שמיר' — לא אומת. אומת: הקטע עין תות–יקנעם ללא אגרה (הורחב ב-2022).$v3$, $v3$[{"title":"Highway 6 (Israel) — Wikipedia","url":"https://en.wikipedia.org/wiki/Highway_6_(Israel)"},{"title":"Bizportal — הקטע עין תות–יקנעם","url":"https://www.bizportal.co.il/car/news/article/20014992"}]$v3$::jsonb, $v3$בכביש 6 אין קופות בכלל: מצלמות מזהות את לוחית הרישוי, והחשבון מגיע הביתה.$v3$, $v3$topic$v3$, $v3${"fr":{"text":"La route 6, « l'autoroute trans-Israël », porte le nom de…","options":["Yitzhak Rabin","David Ben Gourion","Menahem Begin","Golda Meir"],"explanation":"La route 6 s'appelle « route Yitzhak-Rabin », du nom du Premier ministre assassiné en 1995.","category":"Israël aujourd'hui"},"en":{"text":"Road 6, the 'Cross-Israel Highway', is named after —","options":["Yitzhak Rabin","David Ben-Gurion","Menachem Begin","Golda Meir"],"explanation":"Road 6 is called the 'Yitzhak Rabin Highway', after the prime minister assassinated in 1995.","category":"Israel today"},"ru":{"text":"Шоссе 6, «Трансизраильское шоссе», названо в честь…","options":["Ицхака Рабина","Давида Бен-Гуриона","Менахема Бегина","Голды Меир"],"explanation":"Шоссе 6 называется «дорогой Ицхака Рабина» — в честь премьер-министра, убитого в 1995 году.","category":"Израиль сегодня"}}$v3$::jsonb, $v3${"he":{"script":"״דרך יצחק רבין״ — הכביש הארוך בישראל, בלי קופות: מצלמות.","long":"עכשיו עלינו על כביש 6 — כביש חוצה ישראל, שנקרא על שם ראש הממשלה יצחק רבין. זה הכביש הארוך במדינה: מאזור באר שבע בדרום ועד אזור קריית אתא בצפון. רוב הכביש הוא כביש אגרה עם מצלמות במקום קופות, אבל הקטע שאנחנו נוסעים בו עכשיו, מעין תות ליקנעם, הוא בחינם. פעם זה היה כביש 70 צר, והוא הורחב לארבעה נתיבים לכל כיוון.","fact":"בכביש 6 אין קופות בכלל: מצלמות מזהות את לוחית הרישוי, והחשבון מגיע הביתה.","cue":"אחרי מחלף עין תות, כשעולים על כביש 6 צפונה.","caution":"מסמך יוסי טוען שהקטע הצפוני נקרא על שם יצחק שמיר — לא אומת; השאלה עוסקת בשם הכביש כולו."},"fr":{"script":"La « route Yitzhak-Rabin », la plus longue d'Israël, sans péage à barrière : des caméras.","long":"Nous voici sur la route 6, l'autoroute trans-Israël, qui porte le nom du Premier ministre Yitzhak Rabin. C'est la plus longue route du pays, de la région de Beer-Sheva au sud jusqu'à Kiryat Ata au nord. Elle est en grande partie payante, avec des caméras au lieu de péages, mais le tronçon où nous roulons, d'Ein Tut à Yokneam, est gratuit. C'était autrefois l'étroite route 70, élargie à quatre voies dans chaque sens.","fact":"Il n'y a aucune barrière de péage sur la route 6 : des caméras lisent la plaque, et la facture arrive à la maison.","cue":"Après l'échangeur d'Ein Tut, en s'engageant sur la route 6 vers le nord.","caution":"Le document de Yossi dit que la section nord porte le nom d'Yitzhak Shamir : non vérifié. La question porte sur le nom de la route entière."},"en":{"script":"The 'Yitzhak Rabin Highway' — Israel's longest road, no toll booths, just cameras.","long":"We're now on Road 6, the Cross-Israel Highway, named after Prime Minister Yitzhak Rabin. It's the longest road in the country, from the Be'er Sheva area in the south to Kiryat Ata in the north. Most of it is a toll road with cameras instead of booths, but the section we're on now, from Ein Tut to Yokneam, is free. It used to be the narrow Road 70 and was widened to four lanes in each direction.","fact":"Road 6 has no toll booths at all: cameras read your licence plate and the bill arrives at home.","cue":"After the Ein Tut interchange, as we join Road 6 northbound.","caution":"Yossi's notes claim the northern section is named after Yitzhak Shamir — not verified; the question is about the name of the whole road."},"ru":{"script":"«Дорога Ицхака Рабина» — самая длинная в Израиле, без касс: только камеры.","long":"Мы выехали на шоссе 6 — Трансизраильское шоссе, названное в честь премьер-министра Ицхака Рабина. Это самая длинная дорога страны: от района Беэр-Шевы на юге до Кирьят-Аты на севере. Почти вся она платная, с камерами вместо касс, но участок, по которому мы едем, от Эйн-Тута до Йокнеама, бесплатный. Раньше здесь было узкое шоссе 70, а теперь по четыре полосы в каждую сторону.","fact":"На шоссе 6 нет ни одного шлагбаума: камеры считывают номер, и счёт приходит домой.","cue":"После развязки Эйн-Тут, когда выезжаем на шоссе 6 на север.","caution":"По записям Йоси, северный участок назван в честь Ицхака Шамира — не проверено; вопрос о названии всего шоссе."}}$v3$::jsonb, $v3${"stop":"S13","final":false,"topic":"Road 6 Rabin","docs":"יאיר: מתחברים לכביש 6, כביש יצחק רבין, ראש הממשלה החמישי; מתחיל בצומת שוקת ומסתיים במחלף אלונים. יוסי: כביש אגרה; 'כביש 6 צפון נקרא על שם יצחק שמיר' — לא אומת. אומת: הקטע עין תות–יקנעם ללא אגרה (הורחב ב-2022)."}$v3$::jsonb),
($v3$v3:ROAD67-05$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$מושב אליקים הוקם בשנת 1949 על ידי עולים מ…$v3$, $v3$["צרפת","תימן","ארגנטינה","ארצות הברית"]$v3$::jsonb, 1, $v3$אליקים הוא מושב עובדים שהקימו עולי תימן ב-1949, בתקופת העלייה הגדולה.$v3$, $v3$התיישבות$v3$, 2, 45, 12, $v3$מושב של עולי תימן מ-1949. אליקים — שמו המקורי של המלך יהויקים.$v3$, $v3$אנחנו מתקרבים למחלף אליקים. המושב הוקם ב-1949, שנה אחרי קום המדינה, על ידי עולים מתימן — בתקופת העלייה הגדולה, כשבתוך שנים ספורות הוקמו בארץ מאות יישובים חדשים. השם לקוח מהתנ״ך: אליקים היה שמו המקורי של יהויקים מלך יהודה, עד שפרעה נכה מלך מצרים שינה את שמו. אחרי המושב הכביש מתחיל לרדת בתלילות אל עמק יזרעאל.$v3$, $v3$על כביש 6, לפני מחלף אליקים.$v3$, $v3$יאיר: 'מצד ימין', מושב עובדים של יוצאי תימן, 1949, על שם יהויקים מלך יהודה. יוסי: 'מצד ימין', 1949, יושב על קו פרשת המים של רמות מנשה; הערת הבודק: 'הבתים משמאל'. מושב: 32.633, 35.066; מחלף אליקים: 32.636, 35.065 (ויקיפדיה).$v3$, $v3$[{"title":"Elyakim — Wikipedia","url":"https://en.wikipedia.org/wiki/Elyakim"},{"title":"מלכים ב׳ כג, לד","url":"https://he.wikisource.org/wiki/מלכים_ב_כג_לד"},{"title":"מחלף אליקים — ויקיפדיה","url":"https://he.wikipedia.org/wiki/מחלף_אליקים"}]$v3$::jsonb, $v3$'וימלך פרעה נכה את אליקים בן יאשיהו... ויסב את שמו יהויקים' (מלכים ב׳ כג, לד). ולפי מסמך יוסי, המושב יושב על קו פרשת המים של רמות מנשה — מצד אחד המים זורמים מערבה לנחל דליה, ומהצד השני צפונה אל הקישון.$v3$, $v3$check$v3$, $v3${"fr":{"text":"Le moshav d'Elyakim a été fondé en 1949 par des immigrants venus…","options":["de France","du Yémen","d'Argentine","des États-Unis"],"explanation":"Elyakim est un moshav fondé en 1949 par des immigrants du Yémen, à l'époque de la grande vague d'immigration.","category":"Peuplement"},"en":{"text":"Moshav Elyakim was founded in 1949 by immigrants from…","options":["France","Yemen","Argentina","The United States"],"explanation":"Elyakim is a cooperative moshav founded in 1949 by immigrants from Yemen, during the great wave of immigration.","category":"Settlement"},"ru":{"text":"Мошав Эльяким основали в 1949 году репатрианты из…","options":["Франции","Йемена","Аргентины","США"],"explanation":"Эльяким — мошав, основанный в 1949 году выходцами из Йемена в период массовой алии.","category":"Заселение"}}$v3$::jsonb, $v3${"he":{"script":"מושב של עולי תימן מ-1949. אליקים — שמו המקורי של המלך יהויקים.","long":"אנחנו מתקרבים למחלף אליקים. המושב הוקם ב-1949, שנה אחרי קום המדינה, על ידי עולים מתימן — בתקופת העלייה הגדולה, כשבתוך שנים ספורות הוקמו בארץ מאות יישובים חדשים. השם לקוח מהתנ״ך: אליקים היה שמו המקורי של יהויקים מלך יהודה, עד שפרעה נכה מלך מצרים שינה את שמו. אחרי המושב הכביש מתחיל לרדת בתלילות אל עמק יזרעאל.","fact":"'וימלך פרעה נכה את אליקים בן יאשיהו... ויסב את שמו יהויקים' (מלכים ב׳ כג, לד). ולפי מסמך יוסי, המושב יושב על קו פרשת המים של רמות מנשה — מצד אחד המים זורמים מערבה לנחל דליה, ומהצד השני צפונה אל הקישון.","cue":"על כביש 6, לפני מחלף אליקים.","caution":"צד לא אומת: שני המסמכים — מימין; הערת הבודק במסמך יוסי — 'הבתים משמאל'. לא להצביע עד אימות."},"fr":{"script":"Un moshav d'immigrants du Yémen fondé en 1949. Elyakim était le premier nom du roi Joakim.","long":"Nous approchons de l'échangeur d'Elyakim. Le moshav a été fondé en 1949, un an après la création de l'État, par des immigrants du Yémen : c'est l'époque de la grande immigration, où des centaines de nouveaux villages naissent en quelques années. Le nom vient de la Bible : Elyakim était le nom d'origine du roi Joakim de Juda, avant que le pharaon Néko ne le change. Après le moshav, la route descend en pente raide vers la vallée de Jezréel.","fact":"« Le pharaon Néko fit roi Elyakim, fils de Josias… et changea son nom en Joakim » (II Rois 23, 34). Selon le document de Yossi, le moshav se trouve sur la ligne de partage des eaux de Menashe : d'un côté l'eau file vers le Nahal Dalia, de l'autre vers le Kishon.","cue":"Sur la route 6, avant l'échangeur d'Elyakim.","caution":"Côté non vérifié : les deux documents disent à droite ; la note de relecture du document de Yossi dit « les maisons à gauche ». Ne pas montrer avant vérification."},"en":{"script":"A moshav of Yemenite immigrants from 1949. Eliakim was King Jehoiakim's original name.","long":"We're approaching the Elyakim interchange. The moshav was founded in 1949, a year after the state was established, by immigrants from Yemen — the time of mass immigration, when hundreds of new villages sprang up within a few years. The name comes from the Bible: Eliakim was the original name of King Jehoiakim of Judah, until Pharaoh Necho changed it. After the moshav the road begins its steep descent to the Jezreel Valley.","fact":"'Pharaoh Necho made Eliakim son of Josiah king… and changed his name to Jehoiakim' (2 Kings 23:34). According to Yossi's notes, the moshav sits on the Menashe watershed: on one side water flows west to Nahal Dalia, on the other north to the Kishon.","cue":"On Road 6, before the Elyakim interchange.","caution":"Side not verified: both documents say right; the reviewer's note in Yossi's document says 'houses on the left'. Don't point until checked."},"ru":{"script":"Мошав выходцев из Йемена, основан в 1949 году. Эльяким — первое имя царя Иоакима.","long":"Мы подъезжаем к развязке Эльяким. Мошав основали в 1949 году, через год после создания государства, репатрианты из Йемена — это время массовой алии, когда за несколько лет появились сотни новых посёлков. Название библейское: Эльяким — настоящее имя иудейского царя Иоакима, пока фараон Нехо не переименовал его. За мошавом дорога круто спускается к Изреельской долине.","fact":"«И воцарил фараон Нехо Елиакима, сына Иосии… и переменил имя его на Иоаким» (4 Царств 23:34). По записям Йоси, мошав стоит на водоразделе Менаше: с одной стороны вода стекает на запад к ручью Далия, с другой — на север к Кишону.","cue":"На шоссе 6, перед развязкой Эльяким.","caution":"Сторона не проверена: в обоих документах — справа; в пометке проверяющего у Йоси — «дома слева». Не показывать до проверки."}}$v3$::jsonb, $v3${"stop":"S5","final":false,"topic":"Elyakim","docs":"יאיר: 'מצד ימין', מושב עובדים של יוצאי תימן, 1949, על שם יהויקים מלך יהודה. יוסי: 'מצד ימין', 1949, יושב על קו פרשת המים של רמות מנשה; הערת הבודק: 'הבתים משמאל'. מושב: 32.633, 35.066; מחלף אליקים: 32.636, 35.065 (ויקיפדיה)."}$v3$::jsonb),
($v3$v3:ROAD67-06$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$איזו חברה ישראלית שפעלה ביוקנעם נרכשה על ידי אנבידיה בשנת 2020?$v3$, $v3$["מלאנוקס","מובילאיי","ווייז","צ'ק פוינט"]$v3$::jsonb, 0, $v3$אנבידיה השלימה ב-2020 את רכישת מלאנוקס, שפיתחה ביוקנעם טכנולוגיות תקשורת מהירות בין מחשבים ושרתים, בכשבעה מיליארד דולר.$v3$, $v3$הייטק$v3$, 2, 45, 13, $v3$מלאנוקס מיקנעם נקנתה ב-2020 בכ-7 מיליארד דולר. התחלנו ברוטשילד — מסיימים בבינה מלאכותית!$v3$, $v3$אנחנו מתקרבים ליוקנעם, שהפכה מעיירת פיתוח למרכז הייטק חשוב בצפון. חברת מלאנוקס, שפעלה כאן, פיתחה טכנולוגיות תקשורת מהירות שמחברות בין מחשבים ושרתים. בשנת 2020 רכשה אותה אנבידיה בכשבעה מיליארד דולר. ובתחילת 2026 דווח שאנבידיה חתמה על הסכם לשכירת עוד כ-29 אלף מטרים רבועים ביוקנעם. במקביל מתוכנן קמפוס גדול בקריית טבעון. התחלנו במושבות החקלאיות של הברון רוטשילד — ואנחנו מסיימים בעולם הבינה המלאכותית!$v3$, $v3$על כביש 6, לפני מחלף יקנעם.$v3$, $v3$יאיר: אזור התעשייה של יקנעם משמאל, מלאנוקס נקנתה ע״י אנבידיה. יוסי: מלאנוקס, 'נרכשה לפני מספר שנים'. אומת: הרכישה הושלמה ב-27.4.2020 (~6.9 מיליארד דולר). הסכם שכירות של כ-29 אלף מ״ר ביקנעם (מליסרון, פארק עופר) — דווח ב-2026. קמפוס עתידי בקריית טבעון — מקום אחר.$v3$, $v3$[{"title":"NVIDIA completes acquisition of Mellanox (27.4.2020)","url":"https://nvidianews.nvidia.com/news/nvidia-completes-acquisition-of-mellanox-creating-major-force-driving-next-gen-data-centers"},{"title":"Calcalist Tech","url":"https://www.calcalistech.com/ctechnews/article/wrvhykjum"},{"title":"ynet — כלכלה","url":"https://www.ynet.co.il/economy/article/yokra14616608"},{"title":"מרכז הנדל״ן — אנבידיה ביקנעם","url":"https://www.nadlancenter.co.il/article/13866"}]$v3$::jsonb, $v3$מלאנוקס נוסדה ב-1999 ביוקנעם. עשרים שנה אחר כך היא נמכרה באחת העסקאות הגדולות בתולדות ההייטק הישראלי.$v3$, $v3$topic$v3$, $v3${"fr":{"text":"Quelle entreprise israélienne installée à Yokneam a été rachetée par NVIDIA en 2020 ?","options":["Mellanox","Mobileye","Waze","Check Point"],"explanation":"En 2020, NVIDIA a finalisé le rachat de Mellanox, qui développait à Yokneam des technologies de communication ultra-rapide entre ordinateurs et serveurs, pour environ 7 milliards de dollars.","category":"High-tech"},"en":{"text":"Which Israeli company based in Yokneam was acquired by NVIDIA in 2020?","options":["Mellanox","Mobileye","Waze","Check Point"],"explanation":"In 2020 NVIDIA completed its acquisition of Mellanox, which developed high-speed networking between computers and servers in Yokneam, for about 7 billion dollars.","category":"High-tech"},"ru":{"text":"Какую израильскую компанию из Йокнеама купила NVIDIA в 2020 году?","options":["Mellanox","Mobileye","Waze","Check Point"],"explanation":"В 2020 году NVIDIA завершила покупку Mellanox — компании из Йокнеама, создававшей сверхбыструю связь между компьютерами и серверами, — примерно за 7 миллиардов долларов.","category":"Хай-тек"}}$v3$::jsonb, $v3${"he":{"script":"מלאנוקס מיקנעם נקנתה ב-2020 בכ-7 מיליארד דולר. התחלנו ברוטשילד — מסיימים בבינה מלאכותית!","long":"אנחנו מתקרבים ליוקנעם, שהפכה מעיירת פיתוח למרכז הייטק חשוב בצפון. חברת מלאנוקס, שפעלה כאן, פיתחה טכנולוגיות תקשורת מהירות שמחברות בין מחשבים ושרתים. בשנת 2020 רכשה אותה אנבידיה בכשבעה מיליארד דולר. ובתחילת 2026 דווח שאנבידיה חתמה על הסכם לשכירת עוד כ-29 אלף מטרים רבועים ביוקנעם. במקביל מתוכנן קמפוס גדול בקריית טבעון. התחלנו במושבות החקלאיות של הברון רוטשילד — ואנחנו מסיימים בעולם הבינה המלאכותית!","fact":"מלאנוקס נוסדה ב-1999 ביוקנעם. עשרים שנה אחר כך היא נמכרה באחת העסקאות הגדולות בתולדות ההייטק הישראלי.","cue":"על כביש 6, לפני מחלף יקנעם.","caution":"לא להגיד שרואים את בנייני אנבידיה מהאוטובוס — לא אומת. הקמפוס העתידי בקריית טבעון אינו המשרדים ביוקנעם."},"fr":{"script":"Mellanox, de Yokneam, a été rachetée en 2020 pour environ 7 milliards de dollars. Partis de Rothschild, nous finissons avec l'intelligence artificielle !","long":"Nous approchons de Yokneam, ancienne ville de développement devenue un grand pôle high-tech du Nord. La société Mellanox, installée ici, développait des technologies de communication ultra-rapide entre ordinateurs et serveurs. En 2020, NVIDIA l'a rachetée pour environ 7 milliards de dollars. Début 2026, on a appris que NVIDIA louait encore quelque 29 000 m² à Yokneam, et un grand campus est prévu à Kiryat Tivon. Nous sommes partis des colonies agricoles du baron de Rothschild… et nous finissons dans le monde de l'intelligence artificielle !","fact":"Mellanox a été fondée en 1999 à Yokneam. Vingt ans plus tard, elle était vendue lors de l'une des plus grosses transactions de l'histoire de la high-tech israélienne.","cue":"Sur la route 6, avant l'échangeur de Yokneam.","caution":"Ne pas dire qu'on voit les bâtiments de NVIDIA depuis le car : non vérifié. Le futur campus de Kiryat Tivon n'est pas le site de Yokneam."},"en":{"script":"Mellanox from Yokneam was bought in 2020 for about 7 billion dollars. We started with Rothschild — and we end with AI!","long":"We're approaching Yokneam, which grew from a development town into a major high-tech hub of the north. Mellanox, based here, developed high-speed technologies that connect computers and servers. In 2020 NVIDIA bought it for about seven billion dollars. In early 2026 it was reported that NVIDIA signed for about 29,000 more square metres in Yokneam, and a large campus is planned in Kiryat Tivon. We started with Baron Rothschild's farming colonies — and we finish in the world of artificial intelligence!","fact":"Mellanox was founded in Yokneam in 1999. Twenty years later it was sold in one of the biggest deals in Israeli high-tech history.","cue":"On Road 6, before the Yokneam interchange.","caution":"Don't say NVIDIA's buildings are visible from the bus — not verified. The future Kiryat Tivon campus is not the Yokneam offices."},"ru":{"script":"Mellanox из Йокнеама купили в 2020 году примерно за 7 миллиардов долларов. Начали с Ротшильда — заканчиваем искусственным интеллектом!","long":"Мы подъезжаем к Йокнеаму — бывшему городу развития, ставшему крупным центром хай-тека на севере. Компания Mellanox, работавшая здесь, разрабатывала сверхбыстрые технологии связи между компьютерами и серверами. В 2020 году NVIDIA купила её примерно за семь миллиардов долларов. В начале 2026 года сообщили, что NVIDIA арендует в Йокнеаме ещё около 29 тысяч квадратных метров, а в Кирьят-Тивоне планируется большой кампус. Мы начали с сельскохозяйственных колоний барона Ротшильда — а заканчиваем в мире искусственного интеллекта!","fact":"Mellanox была основана в Йокнеаме в 1999 году. Через двадцать лет её продали в одной из крупнейших сделок в истории израильского хай-тека.","cue":"На шоссе 6, перед развязкой Йокнеам.","caution":"Не говорить, что из автобуса видны здания NVIDIA, — не проверено. Будущий кампус в Кирьят-Тивоне — это не офисы в Йокнеаме."}}$v3$::jsonb, $v3${"stop":"S6","final":true,"topic":"NVIDIA Mellanox","docs":"יאיר: אזור התעשייה של יקנעם משמאל, מלאנוקס נקנתה ע״י אנבידיה. יוסי: מלאנוקס, 'נרכשה לפני מספר שנים'. אומת: הרכישה הושלמה ב-27.4.2020 (~6.9 מיליארד דולר). הסכם שכירות של כ-29 אלף מ״ר ביקנעם (מליסרון, פארק עופר) — דווח ב-2026. קמפוס עתידי בקריית טבעון — מקום אחר."}$v3$::jsonb),
($v3$v3:ROAD67-08$v3$, $v3$V3$v3$, $v3$MAIN$v3$, $v3$mcq$v3$, $v3$באיזה ספר בתנ״ך מופיע הפסוק 'מלך יקנעם לכרמל אחד'?$v3$, $v3$["שמות","יהושע","אסתר","רות"]$v3$::jsonb, 1, $v3$יקנעם מופיעה ברשימת 31 המלכים שהכה יהושע (יהושע יב, כב).$v3$, $v3$תנ״ך$v3$, 2, 45, 14, $v3$מוזכרת בספר יהושע: ״מלך יקנעם לכרמל אחד״.$v3$, $v3$יקנעם היא עיר עתיקה מאוד. בספר יהושע היא מופיעה ברשימת המלכים שנכבשו: 'מלך יקנעם לכרמל אחד'. ועוד קודם, במאה ה-15 לפני הספירה, הפרעה תחותמס השלישי כתב את שמה — 'ענקעם' — ברשימת הערים שעבר בהן במסעו לכנען. תל יקנעם, שנחפר בידי הארכאולוג עמנון בן-תור, מכיל שכבות יישוב מתקופת הברונזה ועד התקופה העות'מאנית.$v3$, $v3$אחרי מחלף יקנעם, בכניסה ליקנעם — אחרי שאלת אנבידיה, אם נשאר זמן.$v3$, $v3$יוסי: 'ומלך יוקנעם לכרמל אחד', מסע תחותמס השלישי ('ענקעם'), תל יוקנעם נחפר בידי עמנון בן-תור. יאיר: יקנעם עילית הוקמה ב-1950 כמעברה, מועצה מקומית 1967, עיר 2006. לא אומת שהתל נראה מהכביש.$v3$, $v3$[{"title":"יהושע יב, כב","url":"https://he.wikisource.org/wiki/יהושע_יב_כב"},{"title":"Tel Yokneam — Wikipedia","url":"https://en.wikipedia.org/wiki/Tel_Yokneam"}]$v3$::jsonb, $v3$בתל יקנעם נמצאו יותר מעשרים שכבות יישוב — כמו עוגת שכבות של היסטוריה, אחת מעל השנייה.$v3$, $v3$nearby$v3$, $v3${"fr":{"text":"Dans quel livre de la Bible trouve-t-on le verset « le roi de Yokneam du Carmel, un » ?","options":["L'Exode","Josué","Esther","Ruth"],"explanation":"Yokneam figure dans la liste des 31 rois vaincus par Josué (Josué 12, 22).","category":"Bible"},"en":{"text":"In which book of the Bible do we read 'the king of Jokneam in Carmel, one'?","options":["Exodus","Joshua","Esther","Ruth"],"explanation":"Yokneam appears in the list of the 31 kings defeated by Joshua (Joshua 12:22).","category":"Bible"},"ru":{"text":"В какой книге Библии сказано: «царь Иокнеама при Кармиле — один»?","options":["Исход","Иисус Навин","Есфирь","Руфь"],"explanation":"Йокнеам входит в список 31 царя, побеждённых Иисусом Навином (Нав. 12:22).","category":"Библия"}}$v3$::jsonb, $v3${"he":{"script":"מוזכרת בספר יהושע: ״מלך יקנעם לכרמל אחד״.","long":"יקנעם היא עיר עתיקה מאוד. בספר יהושע היא מופיעה ברשימת המלכים שנכבשו: 'מלך יקנעם לכרמל אחד'. ועוד קודם, במאה ה-15 לפני הספירה, הפרעה תחותמס השלישי כתב את שמה — 'ענקעם' — ברשימת הערים שעבר בהן במסעו לכנען. תל יקנעם, שנחפר בידי הארכאולוג עמנון בן-תור, מכיל שכבות יישוב מתקופת הברונזה ועד התקופה העות'מאנית.","fact":"בתל יקנעם נמצאו יותר מעשרים שכבות יישוב — כמו עוגת שכבות של היסטוריה, אחת מעל השנייה.","cue":"אחרי מחלף יקנעם, בכניסה ליקנעם — אחרי שאלת אנבידיה, אם נשאר זמן.","caution":"לא אומת שתל יקנעם נראה מהכביש. לא להצביע."},"fr":{"script":"Elle figure dans le livre de Josué : « le roi de Yokneam du Carmel, un ».","long":"Yokneam est une ville très ancienne. Le livre de Josué la cite parmi les rois vaincus : « le roi de Yokneam du Carmel, un ». Et bien avant, au XVe siècle avant notre ère, le pharaon Thoutmôsis III inscrivit son nom, « Ain-qenaam », parmi les villes traversées pendant sa campagne en Canaan. Le tell de Yokneam, fouillé par l'archéologue Amnon Ben-Tor, contient des niveaux d'occupation de l'âge du Bronze jusqu'à l'époque ottomane.","fact":"On a identifié à Tel Yokneam plus d'une vingtaine de niveaux d'occupation : un vrai mille-feuille d'histoire.","cue":"Après l'échangeur de Yokneam, à l'entrée de la ville — après la question NVIDIA, s'il reste du temps.","caution":"Visibilité du tell depuis la route non vérifiée. Ne pas montrer."},"en":{"script":"It appears in the Book of Joshua: 'the king of Jokneam in Carmel, one'.","long":"Yokneam is a very old city. The Book of Joshua lists it among the conquered kings: 'the king of Jokneam in Carmel, one'. Even earlier, in the 15th century BCE, Pharaoh Thutmose III recorded its name — 'Ain-qenaam' — among the towns of his campaign in Canaan. Tel Yokneam, excavated by archaeologist Amnon Ben-Tor, holds layers of settlement from the Bronze Age to Ottoman times.","fact":"More than twenty layers of settlement were identified at Tel Yokneam — a real layer cake of history.","cue":"After the Yokneam interchange, entering the town — after the NVIDIA question, if there's time.","caution":"Not verified that the tell is visible from the road. Don't point."},"ru":{"script":"Упоминается в Книге Иисуса Навина: «царь Иокнеама при Кармиле — один».","long":"Йокнеам — очень древний город. Книга Иисуса Навина называет его среди побеждённых царей: «царь Иокнеама при Кармиле — один». А ещё раньше, в XV веке до н. э., фараон Тутмос III записал его название — «Аин-кенаам» — среди городов своего похода в Ханаан. Тель-Йокнеам, раскопанный археологом Амноном Бен-Тором, хранит слои поселений от бронзового века до османской эпохи.","fact":"На Тель-Йокнеаме выделили больше двадцати слоёв поселений — настоящий слоёный пирог истории.","cue":"После развязки Йокнеам, при въезде в город — после вопроса об NVIDIA, если останется время.","caution":"Не проверено, виден ли тель с дороги. Не показывать."}}$v3$::jsonb, $v3${"stop":"S8","final":false,"topic":"Biblical Yokneam","docs":"יוסי: 'ומלך יוקנעם לכרמל אחד', מסע תחותמס השלישי ('ענקעם'), תל יוקנעם נחפר בידי עמנון בן-תור. יאיר: יקנעם עילית הוקמה ב-1950 כמעברה, מועצה מקומית 1967, עיר 2006. לא אומת שהתל נראה מהכביש."}$v3$::jsonb)
